insert into programs (id,name,country,cc,levels,funding,base_adm,base_sch,req,deadline,deadline_md,apply_open_md,note,fields,source_url,verified,verified_at,lang_year,exam,available_kz) values
('boell','Heinrich-Böll-Stiftung (Германия)','Германия','de',array['master','phd'],'Ежемесячная стипендия по ставкам BMBF (ориентир: ~€992/мес магистратура, ~€1 450/мес PhD) + доплаты на медстраховку/семью; обучение в гос. вузах Германии бесплатно. Продолжительность — весь нормативный срок программы.',0.15,0.15,'{"academics": 7, "language": 6.5, "budget": 0}'::jsonb,'1 марта','03-01','01-15','Официально: Heinrich-Böll-Stiftung Scholarship for International Students (Studienwerk). Только магистратура и PhD (бакалавриат для иностранцев закрыт). Приоритет — кандидаты из стран DAC-списка (Казахстан входит), ещё не проживающие в Германии. Отбор с интервью, важна общественная активность, экология, права человека; немецкий B2 обязателен.',null,'https://www.boell.de/en/application',false,null,false,null,true),
('kas_intl','Konrad-Adenauer-Stiftung (Германия)','Германия','de',array['master','phd'],'До €992/мес (магистратура, постдиплом) и до €1 400/мес (PhD) + доплаты на страховку; стандартно 2 года (магистратура) / 3 года (PhD). Обучение в гос. вузах бесплатно.',0.12,0.12,'{"academics": 7, "language": 6.5, "budget": 0}'::jsonb,'15 июля','07-15',null,'Официально: Konrad-Adenauer-Stiftung — International Talent Development (scholarships for international students and doctoral candidates). Нужен немецкий B2 даже для англоязычных программ, отбор с интервью (в т.ч. в региональных офисах KAS). Ценностный фонд ХДС: важна общественная/политическая активность. Возрастного лимита нет.',null,'https://www.kas.de/en/web/begabtenfoerderung-und-kultur/international-talent-development',false,null,false,null,true),
('x-fes-foreign-students','Friedrich-Ebert-Stiftung (Германия)','Германия','de',array['bachelor','master','phd'],'€992/мес (студенты) / €1 500/мес (аспиранты) + €276 семейная доплата; медстраховка. Обучение в гос. вузах бесплатно.',null,null,null,'по семестрам; подача возможна только после зачисления в немецкий вуз (магистр…',null,null,'Официально: Friedrich-Ebert-Stiftung — Scholarship for foreign students (Grundförderung für Ausländer:innen). Подавать можно ТОЛЬКО уже будучи зачисленным/обучающимся в вузе Германии — нельзя получить до переезда. Обязательны немецкий и подтверждённая общественно-политическая активность; ценностный фонд СДПГ.',null,'https://www.fes.de/studienfoerderung/information-in-english',false,null,false,null,true),
('x-hanns-seidel','Hanns-Seidel-Stiftung (Германия)','Германия','de',array['master','phd'],'Студенческая стипендия до €855/мес + €300/мес на учебные расходы; аспирантская до €1 650/мес (данные сайта HSS). Обучение в гос. вузах бесплатно.',null,null,null,'15 января','01-15','12-15','Официально: Hanns-Seidel-Stiftung — Stipendium für internationale Studierende und Promovierende. Фонд ХСС (Бавария): отбор с интервью, нужен немецкий и общественная активность; для иностранцев — как правило магистратура/PhD в немецком вузе. Две волны в год.',null,'https://www.hss.de/stipendium/',false,null,false,null,true),
('rosalux','Rosa-Luxemburg-Stiftung (Германия)','Германия','de',array['master','phd'],'Стипендия по стандартным ставкам немецких фондов (BMBF): ~€992/мес магистратура, ~€1 450/мес PhD + доплаты на страховку; обучение бесплатно.',0.12,0.12,'{"academics": 7, "language": 6.5, "budget": 0}'::jsonb,'1 октября','10-01',null,'Официально: Rosa-Luxemburg-Stiftung — Scholarships for international students (Studienwerk). Для иностранцев — только магистратура (Master only) и PhD (кроме медицины/стоматологии/ветеринарии); нужно проживать в Германии на период учёбы и планировать возврат на родину. Немецкий B2, левые/социально-политические ценности фонда, интервью.',null,'https://www.rosalux.de/en/foundation/studienwerk',false,null,false,null,true),
('fnf_intl','Friedrich-Naumann-Stiftung (Германия)','Германия','de',array['master','phd'],'€992/мес (магистратура), до €1 500/мес (PhD) + доплаты на супруга €276 и ребёнка €259, медстраховка. Обучение бесплатно.',0.12,0.12,'{"academics": 7, "language": 6.5, "budget": 0}'::jsonb,'30 апреля','04-30','04-01','Официально: Friedrich-Naumann-Stiftung für die Freiheit — Stipendium für ausländische Studierende und Promovierende. Иностранцы — только очная магистратура или PhD в Германии; до начала выплат нельзя жить в Германии >15 месяцев (кроме учёбы). Заявка и собеседование полностью на немецком; либеральный фонд (СвДП).',null,'https://www.freiheit.org/scholarships',false,null,false,null,true),
('daad_master','DAAD Master Studies (все дисциплины)','Германия','de',array['master'],'€992/мес на 10–24 мес + медстраховка, проездной грант, при необходимости доплата на аренду/семью, оплата языкового курса; обучение в гос. вузах бесплатно.',0.22,0.22,'{"academics": 7.5, "language": 6.5, "budget": 0}'::jsonb,'осень (обычно окт–ноя, approx) — через DAAD Information Centre Алматы; даты о…',null,null,'Официально: DAAD Study Scholarships — Master Studies for All Academic Disciplines. Подача через DAAD-портал и офис в Казахстане; нужен диплом бакалавра не старше 6 лет, отличная успеваемость, мотивация; часто требуют одновременно подать в вузы. Не путать с EPOS/Helmut-Schmidt (уже в каталоге).',null,'https://www.daad.de/en/studying-in-germany/scholarships/daad-scholarships/',false,null,false,null,true),
('daad_phd','DAAD Research Grants (PhD)','Германия','de',array['phd'],'€1 300/мес до 4 лет + медстраховка, проездной грант, исследовательская надбавка €460/год, доплата на аренду и семью, оплата языкового курса.',0.18,0.18,'{"academics": 7.5, "language": 6.5, "budget": 0}'::jsonb,'осень (approx, по стране — см. DAAD Алматы); дедлайны публикуются ежегодно во…',null,null,'Официально: DAAD Research Grants — Doctoral Programmes in Germany. Нужны диплом магистра, письмо-согласие научного руководителя в Германии и проработанный исследовательский план; отбор комиссией DAAD. Доступно гражданам почти всех стран, включая Казахстан.',null,'https://www2.daad.de/deutschland/stipendium/datenbank/en/21148-scholarship-database/?detail=57135739',false,null,false,null,true),
('x-daad-summer-courses','DAAD летние языковые курсы','Германия','de',array['language-year'],'Оплата летнего курса (4 недели) и проживания + разовая выплата €475 + проездной грант и страховка.',null,null,null,'30 октября','10-30','09-01','Официально: DAAD University Summer Courses in Germany for Foreign Students and Graduates (Hochschulsommerkurse). Для студентов бакалавриата (после 2 курсов) и магистратуры всех специальностей; курс 18+ дней в немецком вузе летом. Это краткосрочный языковой грант, а не полный год, но хорошая «ступень» к DAAD-магистратуре.',null,'https://www2.daad.de/deutschland/stipendium/datenbank/en/21148-scholarship-database/?detail=50035295',false,null,false,null,true),
('ista_phd','ISTA PhD (Австрия)','Австрия','at',array['phd'],'Полностью оплачиваемая позиция: зарплата €3 053–3 673/мес брутто (2026), полное соцстрахование; обучение и подача бесплатны.',0.1,0.95,'{"academics": 8.5, "language": 7, "budget": 0}'::jsonb,'8 января','01-08',null,'Официально: ISTA PhD Program (Institute of Science and Technology Austria). Можно поступать сразу после бакалавра; треки: биология, химия/материалы, CS, data science, математика, нейронауки, физика. Очень конкурентный отбор с интервью в кампусе под Веной.',array['sci','it','eng'],'https://phd.pages.ista.ac.at/phd-application-admission/',false,null,false,null,true),
('unige_excellence','Excellence Master Fellowships (Женева)','Швейцария','ch',array['master'],'CHF 10 000–15 000 в год на весь срок магистратуры (3–4 семестра), без преподавательских обязанностей; плата за обучение в UNIGE — CHF 500/семестр.',0.15,0.15,'{"academics": 8, "language": 6.5, "budget": 0}'::jsonb,'28 февраля (ориентировочно)','02-28',null,'Официально: University of Geneva — Excellence Master Fellowships (Faculty of Science). Только факультет наук: астрономия, биология, химия/биохимия, CS, математика, физика, фармацевтика, науки о Земле. Отбор по досье (CV, транскрипт, мотивация, 2 рекомендации); продление после 1-го семестра при хороших оценках.',array['sci'],'https://www.unige.ch/sciences/en/enseignements/formations/masters/excellencemasterfellowships',false,null,false,null,true),
('unil_master','UNIL Master''s Grant (Лозанна)','Швейцария','ch',array['master'],'CHF 1 600/мес на нормативный срок магистратуры + освобождение от платы за обучение (остаётся CHF 80/семестр). Не покрывает всю стоимость жизни.',0.08,0.08,'{"academics": 8, "language": 6.5, "budget": 0}'::jsonb,'1 ноября','11-01',null,'Официально: Unil Master''s Scholarship (UNIL Master''s grants, Université de Lausanne). ~10 стипендий в год, только для выпускников зарубежных вузов с очень высокими оценками. Не для медицины, педагогики и большинства юридических магистратур; 2 рекомендательных письма напрямую от авторов.',null,'https://www.unil.ch/unil/en/home/menuinst/etudier/mobilite-et-echange/etudiantes-et-etudiants-internationaux/etudiantes-internationaux-reguliers/bourse-de-master.html',false,null,false,null,true),
('iheid','Geneva Graduate Institute (IHEID)','Швейцария','ch',array['master'],'Полная или частичная стипендия (по формулировке института — максимум CHF 20 000 на два года) и/или снижение платы за обучение; институт тратит >CHF 2 млн в год на поддержку студентов.',0.2,0.2,'{"academics": 7.5, "language": 7, "budget": 3}'::jsonb,'15 января (ориентировочно)','01-15',null,'Официально: Geneva Graduate Institute (IHEID) — Scholarships and financial aid for Master programmes. Отдельно подавать не нужно — заявка на финансовую помощь идёт в общей анкете; решение по сочетанию академических успехов и финансовой нужды. Профиль: международные отношения, развитие, право, экономика.',array['hum','law','bus'],'https://www.graduateinstitute.ch/fees-financial-aid',false,null,false,null,true),
('leiden_lexs','Leiden Excellence Scholarship (LExS)','Нидерланды','nl',array['master'],'Фиксированные суммы к оплате обучения: €10 000 / €15 000 / €17 500 / €18 500 / €19 000 (из ~€20–25 тыс. non-EU tuition); проживание не покрывается.',0.1,0.1,'{"academics": 8.5, "language": 7, "budget": 0}'::jsonb,'1 декабря','12-01',null,'Официально: Leiden University Excellence Scholarship (LExS). Только для не-EEA студентов очной магистратуры (кроме обычных LLM и MSc юрфака); ~25 стипендий на >1000 заявок. Не полная стипендия — нужно доказать остаток средств для визы.',null,'https://www.universiteitleiden.nl/en/scholarships/sea/leiden-university-excellence-scholarship-lexs',false,null,false,null,true),
('um_high_potential','Maastricht NL-High Potential','Нидерланды','nl',array['master'],'Полное покрытие: на проживание €20 150 (13 мес) или €38 750 (25 мес) + плата за обучение, виза, медстраховка.',0.08,0.08,'{"academics": 8.5, "language": 7, "budget": 0}'::jsonb,'1 февраля','02-01','10-01','Официально: UM NL-High Potential Scholarship (Maastricht University). Только для не-EU/EEA, возраст до 35 лет на 1 сентября, GPA ≥7.5/10, желательно без имеющейся магистратуры; сначала нужно полностью подать в программу через Studielink. Выигрывают ~2% заявителей.',null,'https://www.maastrichtuniversity.nl/studeren/toelating-inschrijving/financing-your-studies/scholarships/maastricht-university-nl-high',false,null,false,null,true),
('twente_uts','University of Twente Scholarship (UTS)','Нидерланды','nl',array['master'],'€3 000–22 000 на один год (в зависимости от программы); при хорошей успеваемости возможен второй год.',0.15,0.15,'{"academics": 8, "language": 6.5, "budget": 2}'::jsonb,'1 апреля','04-01',null,'Только не-EU/EEA с (условным) зачислением на MSc в Twente; нужно входить в топ-5–10% своего выпуска. Часто покрывает лишь часть — уточняйте сумму по программе.',null,'https://www.utwente.nl/en/education/scholarship-finder/university-of-twente-scholarship/',false,null,false,null,true),
('master_mind','Master Mind (Фландрия, Бельгия)','Бельгия','be',array['master'],'€10 225 в год + освобождение от платы за обучение (tuition fee waiver) на 1 год (60 ECTS) или 2 года (120 ECTS).',0.1,0.1,'{"academics": 8.5, "language": 7, "budget": 2}'::jsonb,'15 января (ориентировочно)','01-15',null,'Официально: Master Mind Scholarships (Government of Flanders). Открыто всем гражданствам, кроме России; нужен GPA ≥3.5/4.0 и IELTS 7.0. Подаёте через фламандский вуз (каждый выдвигает до 20 кандидатов) — сначала заявка на магистратуру, потом номинация.',null,'https://www.studyinflanders.be/scholarships/master-mind-scholarships/eligibility-criteria',false,null,false,null,true),
('boutmy','Émile Boutmy (Sciences Po)','Франция','fr',array['bachelor','master'],'Бакалавриат: полное освобождение от tuition или скидка €9 500/год; магистратура: скидка €18 500/год на оба года. Возможны допвыплаты на проживание отдельным спонсорским стипендиатам.',0.2,0.2,'{"academics": 7.5, "language": 6.5, "budget": 2}'::jsonb,'1 февраля','02-01','10-01','Официально: Émile Boutmy Scholarship (Sciences Po). Только для граждан не-ЕС, чья семья не платит налоги в ЕС, впервые поступающих в Sciences Po; учитываются и доход семьи, и academic excellence. Нельзя подать после зачисления — только в анкете поступления.',array['hum','law','bus'],'https://www.sciencespo.fr/students/en/fees-funding/bursaries-financial-aid/emile-boutmy-scholarship/',false,null,false,null,true),
('paris_saclay','Paris-Saclay International Master''s','Франция','fr',array['master'],'€10 000 в год (на M1 и/или M2, продлевается на 2-й год) + до €900/год на дорогу и визу; обучение в гос. вузе ~€250/год.',0.18,0.18,'{"academics": 8, "language": 6.5, "budget": 2}'::jsonb,'31 марта (ориентировочно)','03-31',null,'Официально: Université Paris-Saclay International Master''s Scholarships Program. Иностранцы до 30 лет, впервые учащиеся во Франции, зачисленные на магистратуру Paris-Saclay; кандидатуру выдвигает координатор программы. Нельзя совмещать с Eiffel/France Excellence/Erasmus Mundus.',null,'https://www.universite-paris-saclay.fr/en/admission/bourses-et-aides-financieres/international-masters-scholarships-program',false,null,false,null,true),
('ens_intl','ENS International Selection (Париж)','Франция','fr',array['master'],'€1 000/мес в течение 3 лет + комната в кампусе ENS; обучение бесплатно (диплом ENS + магистратура).',0.05,0.95,'{"academics": 9, "language": 7, "budget": 0}'::jsonb,'15 декабря (ориентировочно)','12-15','10-01','Официально: ENS International Selection (École normale supérieure – PSL, Paris). Возраст до 26 лет на 1 декабря, минимум 1–2 года бакалавриата в зарубежном вузе, нельзя жить во Франции >10 мес в год отбора и подавать повторно. Письменные и устные экзамены в Париже; крайне конкурентно.',array['sci','hum'],'https://www.ens.psl.eu/en/academics/admissions/international-selection',false,null,false,null,true),
('ampere_lyon','Ampère Excellence (ENS de Lyon)','Франция','fr',array['master'],'€1 000/мес на 12 месяцев (1 учебный год), продляемо на M2 при условиях; обучение в ENS ~€250/год.',0.08,0.08,'{"academics": 8.5, "language": 7, "budget": 0}'::jsonb,'23 января','01-23','11-14','Официально: Ampère Scholarships of Excellence (ENS de Lyon). Для иностранных студентов, поступающих в магистратуру ENS Lyon по точным наукам, искусствам и гуманитарным наукам; заявка на стипендию подаётся вместе с заявкой на магистратуру. Результаты в середине марта.',null,'https://www.ens-lyon.fr/en/studies/admissions/application-masters-degrees-and-scholarships',false,null,false,null,true),
('iyt_italy','Invest Your Talent in Italy (IYT)','Италия','it',array['master'],'€10 800 (выплаты поквартально, ~9 мес/год) + освобождение от платы за обучение (остаются ~€156 регионального сбора) + курс итальянского + обязательная стажировка в итальянской компании.',0.2,0.2,'{"academics": 7, "language": 6.5, "budget": 2}'::jsonb,'11 мая (ориентировочно)','05-11','03-01','Официально: Invest Your Talent in Italy (IYT) — MAECI / Uni-Italia. Казахстан входит в список стран IYT. Только англоязычные магистратуры-партнёры по инженерии/IT/экономике/дизайну; отбор по академическим результатам и мотивации, обязателен интерншип.',array['eng','it','bus','art','sci'],'https://www.unipi.it/en/education/registration/enrolment-and-registration/enrolment-for-international-students/invest-your-talent-in-italy-scholarships/',false,null,false,null,true),
('unibo_talents','International Talents @Unibo (Болонья)','Италия','it',array['master'],'30 грантов по €6 500 в год на 2 года + полное освобождение от платы за обучение (остаётся ~€157 сборов).',0.2,0.2,'{"academics": 7.5, "language": 6.5, "budget": 2}'::jsonb,'30 мая (ориентировочно)','05-30',null,'Официально: International Talents @Unibo — study grants for international students (University of Bologna). Для первокурсников магистратуры с дипломом, полученным вне итальянской системы (гражданство не важно). Ранжирование строго по GRE General (мин. V+Q 290, AW 3.0) — нужно сдать тест заранее. Есть требование по доходу семьи (ISEE €16 000–35 000) и возраст до 30 лет.',null,'https://bandi.unibo.it/s/diri/bando-international-talents-unibo-borse-di-studio-per-studenti-internazionali-che-si-immatricolano-ai-corsi-di-laurea-magistrale-dell-universita-di-bologna-per-l-a-a-2025-26/call-for-application/en-bando_international-talents-2526_17-1-25.pdf/@@download/file/EN%20BANDO_INTERNATIONAL%20TALENTS%202526_17-1-25.pdf',false,null,false,null,true),
('padua_excellence','Padua International Excellence','Италия','it',array['bachelor','master'],'€8 000 брутто в год + освобождение от платы за обучение (остаются региональный сбор и гербовая марка); до 2 лет магистратура / 3 года бакалавриат; до 68 стипендий.',0.15,0.15,'{"academics": 8, "language": 6.5, "budget": 0}'::jsonb,'2 февраля (ориентировочно)','02-02','11-01','Официально: Padua International Excellence Scholarship Programme (Università di Padova). Отдельно не подаётся — рассматриваются все, кто подал в англоязычную программу в первом раунде (иностранный диплом/аттестат, не резидент Италии). Нужно набрать ≥20 ECTS к 30 ноября, иначе стипендия отзывается.',null,'https://www.unipd.it/en/padua-excellence',false,null,false,null,true),
('topolito','TOPoliTO (Politecnico di Torino)','Италия','it',array['master'],'€8 000 брутто в год (~€7 370 нетто) на 2 года магистратуры; плата за обучение, дорога и жильё НЕ покрываются (tuition для иностранцев по доходу семьи, часто снижена).',0.1,0.1,'{"academics": 8, "language": 6.5, "budget": 0}'::jsonb,'31 августа (ориентировочно)','08-31',null,'Официально: TOPoliTO Scholarships (Politecnico di Torino). ~10 стипендий (6 инженерия, 4 архитектура) для обладателей зарубежного бакалавра, не живших в Италии последние 5 лет; ранжирование по GRE. Небольшая программа — рассматривать как дополнение к DSU/EDISU (уже в каталоге).',array['eng','it'],'https://www.polito.it/en/education/international-students/financial-aid',false,null,false,null,true),
('inphinit','«la Caixa» INPhINIT PhD (Испания)','Испания','es',array['phd'],'Полная оплата труда и tuition за докторантуру + бюджет на исследования; 30 стипендий, до 4 лет (в прошлые годы ~€35 800/год + €3 564/год на расходы).',0.08,0.95,'{"academics": 9, "language": 7, "budget": 0}'::jsonb,'28 января (ориентировочно)','01-28','11-01','Официально: "la Caixa" Foundation Doctoral INPhINIT Fellowships — Incoming. Любое гражданство; нельзя жить/работать в Испании или Португалии >12 мес за последние 3 года и иметь >4 лет исследовательского опыта. Только центры с аккредитацией Severo Ochoa / María de Maeztu / ISCIII (или португальские «excellent»); STEM-профиль, интервью.',array['sci','eng','it','med'],'https://lacaixafoundation.org/en/doctoral-inphinit-fellowships-incoming-call',false,null,false,null,true),
('x-fct-phd-portugal','FCT PhD Studentships (Португалия)','Португалия','pt',array['phd'],'Ежемесячная стипендия (ориентир 2025/26: ~€1 260/мес) до 48 месяцев + оплата tuition докторантуры и соцстрахование; 1 600 стипендий в 2026 (600 — в неакадемической среде).',null,null,null,'31 марта (ориентировочно)','03-31','03-01','Официально: FCT PhD Research Studentships (Bolsas de Investigação para Doutoramento, Fundação para a Ciência e a Tecnologia). Открыто гражданам любых стран, зачисленным (или готовым зачислиться) в докторантуру португальского вуза; нужны научный руководитель и принимающая исследовательская единица. Конкуренция высокая (3.6 тыс. заявок в 2026).',null,'https://www.fct.pt/concurso-de-bolsas-de-doutoramento-2026-regista-novo-maximo-de-candidaturas/',false,null,false,null,true),
('kth_scholarship','KTH Scholarship (Швеция)','Швеция','se',array['master'],'Полное покрытие платы за обучение (~SEK 155 000–200 000/год) на 1-й и 2-й год; проживание не покрывается.',0.08,0.08,'{"academics": 8.5, "language": 7, "budget": 0}'::jsonb,'15 января','01-15','12-01','Официально: KTH Scholarship (KTH Royal Institute of Technology). Только для fee-paying (не-EU) студентов, поставивших KTH-программу первым приоритетом на universityadmissions.se и оплативших сбор. В 2025 получили ~8% (65 из 803 заявителей).',array['eng','it','sci'],'https://www.kth.se/en/studies/master/admissions/scholarships/kth-scholarship-1.72827',false,null,false,null,true),
('lund_global','Lund Global Scholarship (Швеция)','Швеция','se',array['bachelor','master'],'Покрытие 25–100% платы за обучение (сумма зависит от факультета); проживание не покрывается.',0.12,0.12,'{"academics": 8, "language": 6.5, "budget": 2}'::jsonb,'16 февраля','02-16','02-01','Официально: Lund University Global Scholarship. Только граждане вне EU/EEA/Швейцарии, обязанные платить tuition, подавшие Lund первым приоритетом; отбор по академическим результатам, финансовая нужда не учитывается. Мотивационное письмо до 600 слов.',null,'https://www.lunduniversity.lu.se/admissions/scholarships-and-awards/lund-university-global-scholarship',false,null,false,null,true),
('uppsala_global','Uppsala Global Scholarship (Швеция)','Швеция','se',array['master'],'Полное покрытие платы за обучение на весь срок магистратуры; проживание не покрывается.',0.08,0.08,'{"academics": 8.5, "language": 7, "budget": 0}'::jsonb,'2 февраля','02-02','01-16','Официально: Uppsala University Global Scholarship (Master''s). Для fee-paying студентов вне EU/EEA; отдельная заявка на стипендию после подачи в программу через universityadmissions.se. Отбор по академическим результатам; программы Uppsala первым приоритетом.',null,'https://www.uu.se/en/study/masters-studies/scholarships/uppsala-university-scholarships',false,null,false,null,true),
('chalmers_ipoet','Chalmers IPOET / Avancez (Швеция)','Швеция','se',array['master'],'Снижение платы за обучение на 75% на 4 семестра (IPOET — финансирует правительство Швеции; Avancez — Chalmers); при отличных результатах 1-го года — до 85%. Проживание не покрывается.',0.15,0.15,'{"academics": 8, "language": 6.5, "budget": 2}'::jsonb,'15 января','01-15','11-25','Официально: Chalmers IPOET and Avancez Scholarships (Chalmers University of Technology). Доступно всем fee-paying (не-EU) студентам, подавшим на магистратуру Chalmers; нужен номер заявки universityadmissions.se. Финансовое положение не учитывается — только академические достижения.',array['eng','it','sci'],'https://www.chalmers.se/en/education/application-and-admission/scholarships-for-fee-paying-students/',false,null,false,null,true),
('ki_global','KI Global Master''s (Karolinska)','Швеция','se',array['master'],'Полное покрытие платы за обучение на весь срок магистратуры; проживание, дорога и жильё не покрываются.',0.06,0.06,'{"academics": 8.5, "language": 7, "budget": 0}'::jsonb,'15 февраля','02-15','02-01','Официально: KI Global Master''s Scholarship for fee-paying students (Karolinska Institutet). Только для fee-paying студентов, поставивших программу KI первым приоритетом; ~10–12 стипендий в год, по одной на программу (лучший по KI CV-форме). Медицина/биомедицина/общественное здоровье.',array['med'],'https://education.ki.se/bachelors-masters-studies/scholarships/the-ki-global-masters-scholarships-for-fee-paying-students',false,null,false,null,true),
('imperial_phd','Imperial President''s PhD (Лондон)','Великобритания','gb',array['phd'],'Полная оплата tuition + стипендия £26 500/год (2026–27) + £2 000/год на расходные материалы в первые 3 года; 50 стипендий.',0.08,0.08,'{"academics": 9, "language": 7, "budget": 0}'::jsonb,'12 января (ориентировочно)','01-12','10-01','Официально: President''s PhD Scholarships (Imperial College London). Без ограничений по гражданству; нужны диплом с отличием (first class / distinction) и предварительное согласие научного руководителя. Заявка через обычный doctoral admissions с research proposal.',null,'https://www.imperial.ac.uk/study/fees-and-funding/postgraduate-doctoral/grants-scholarships/presidents-phd/',false,null,false,null,true),
('ucl_res','UCL Research Excellence (PhD)','Великобритания','gb',array['phd'],'Полная оплата tuition (Overseas) + стипендия £22 780/год (ставка 2025/26) на исследовательскую часть программы + до £1 200/год на исследования; 40 стипендий.',0.08,0.08,'{"academics": 9, "language": 7, "budget": 0}'::jsonb,'9 января (ориентировочно)','01-09','10-01','Официально: UCL Research Excellence Scholarship (UCL-RES). Для кандидатов из любой страны, подавших полную заявку на PhD в UCL; нужен диплом уровня UK 2:1+. Отдельная заявка на стипендию, конкурс очень высокий.',null,'https://www.ucl.ac.uk/scholarships/research-excellence-scholarship',false,null,false,null,true),
('lse_gss','LSE Graduate Support Scheme','Великобритания','gb',array['master'],'£5 000–20 000 (need-based, разово на год) в дополнение к другим источникам; полный tuition не покрывает.',0.3,0.3,'{"academics": 7.5, "language": 7, "budget": 4}'::jsonb,'23 апреля (ориентировочно)','04-23','10-01','Официально: LSE Graduate Support Scheme (GSS). Открыт всем гражданствам на taught master''s/diploma (кроме executive/модульных программ); оценивается финансовая нужда, а не успеваемость. Заявка через Graduate Financial Support после подачи на поступление; не влияет на решение о приёме.',array['hum','bus','law'],'https://www.lse.ac.uk/study-at-lse/Graduate/fees-and-funding/graduate-support-scheme',false,null,false,null,true),
('warwick_phd','Warwick Chancellor''s PhD','Великобритания','gb',array['phd'],'Полная оплата academic fees + стипендия по ставке UKRI (~£20 780/год) на 3.5 года + разовый грант RTSG £5 000; иммиграционная поддержка.',0.08,0.08,'{"academics": 8.5, "language": 7, "budget": 0}'::jsonb,'11 декабря (ориентировочно)','12-11','10-01','Официально: Chancellor''s International / Chancellor''s Scholarships (University of Warwick, PGR). Любое гражданство и fee status; нужен оффер на PGR-программу Warwick на октябрь, отсрочка невозможна. Проект по любой дисциплине или междисциплинарный в рамках Research Spotlights.',null,'https://warwick.ac.uk/services/dc/schols_fund/scholarships_and_funding/',false,null,false,null,true),
('cam_intl','Cambridge International Scholarship','Великобритания','gb',array['phd'],'Полная оплата University Composition Fee (International) + maintenance (~£20 000+/год) + иммиграционный медсбор; ~80 стипендий в год.',0.08,0.08,'{"academics": 9, "language": 7.5, "budget": 0}'::jsonb,'3 декабря (ориентировочно)','12-03','09-01','Официально: Cambridge International Scholarship (Cambridge Trust). Все страны, кроме UK/Ирландии, со статусом Overseas; отдельной заявки нет — отмечаете funding в общей аппликации в Cambridge до дедлайна по курсу. Решения март–июль; если не связались до конца июля — отказ.',null,'https://www.student-funding.cam.ac.uk/fund/cambridge-international-scholarship-2024',false,null,false,null,true),
('edinburgh_edcs','Edinburgh Doctoral College (EDCS)','Великобритания','gb',array['phd'],'Полная оплата tuition + стипендия по ставке UKRI (£20 780 в 2025–26) на 3–4 года (в зависимости от школы).',0.08,0.08,'{"academics": 8.5, "language": 7, "budget": 0}'::jsonb,'31 января (ориентировочно)','01-31','10-01','Официально: Edinburgh Doctoral College Scholarships (EDCS, University of Edinburgh). Открыто UK и overseas кандидатам на 1-й год PhD; нужен диплом уровня UK first/2:1. Сначала заявка на поступление, затем онлайн-заявка на стипендию через MyEd (Informatics и Physics рассматривают автоматически); в большинстве школ 1 стипендия.',null,'https://registryservices.ed.ac.uk/student-funding/postgraduate/international/doctoral-college',false,null,false,null,true),
('standrews_ug','St Andrews International Excellence (бак.)','Великобритания','gb',array['bachelor'],'Полная оплата tuition на весь срок бакалавриата (одна стипендия в год); проживание не покрывается.',0.1,0.1,'{"academics": 8.5, "language": 7, "budget": 5}'::jsonb,'27 января','01-27','10-01','Официально: International Excellence Scholarship (University of St Andrews, undergraduate). Только один победитель среди overseas-абитуриентов (кроме медицины и совместного BA с William & Mary); заявка через портал после подачи на курс, победитель обязан быть Student Ambassador. Есть и частичные International Undergraduate Scholarships.',null,'https://www.st-andrews.ac.uk/study/scholarships/scholarships-catalogue/undergraduate-scholarships/international-excellence-scholarship/',false,null,false,null,true),
('standrews_phd','St Andrews World-Leading PhD','Великобритания','gb',array['phd'],'Полная оплата tuition + стипендия £20 467/год (2026–27); до 6 стипендий.',0.08,0.08,'{"academics": 8.5, "language": 7, "budget": 0}'::jsonb,'20 января','01-20','10-01','Официально: St Leonard''s College World-Leading Doctoral Scholarships (University of St Andrews). Для любого fee status, включая Overseas; нужна поданная заявка на PhD в St Andrews. Отбор студентом-инициированных проектов (student-led) при поддержке школы/руководителя.',null,'https://www.st-andrews.ac.uk/study/fees-and-funding/scholarships/scholarships-catalogue/postgraduate-scholarships/world-leading-scholarships-student-led/',false,null,false,null,true),
('ucd_global','UCD Global Excellence (Дублин)','Ирландия','ie',array['bachelor','master'],'50% или 100% платы за обучение (tuition ~€20–30 тыс./год) на бакалавриат и taught master''s; проживание не покрывается; ежегодная переоценка.',0.25,0.25,'{"academics": 7.5, "language": 6.5, "budget": 3}'::jsonb,'31 марта (ориентировочно)','03-31','10-01','Официально: UCD Global Excellence Scholarships (University College Dublin). Только для абитуриентов со статусом non-EU fee; нужно иметь оффер на программу UCD и подать как можно раньше. Не продлевается автоматически — успеваемость проверяют каждый год.',null,'https://www.ucd.ie/global/study-at-ucd/scholarshipsfinances/scholarships/globalexcellencescholarships/',false,null,false,null,true),
('x-polonista-nawa','Polonista NAWA (Польша)','Польша','pl',array['bachelor-exchange','master','phd','research'],'Стипендия 2 000 PLN/мес студентам и 3 300 PLN/мес докторантам на 1–2 семестра частичного обучения или на полную магистратуру по полонистике в польском вузе; для учёных — исследовательские стажировки 3–12 мес. Обучение в государственных вузах без платы.',null,null,null,'3 апреля (ориентировочно)','04-03','02-15','Официально: Polonista NAWA — scholarship programme for students of Polish studies (Program dla studentów polonistyki). Только для тех, кто изучает польскую филологию/полонистику или славистику с польским; заявители со всего мира, гражданство не ограничено. Нужно самому получить согласие принимающего вуза.',null,'https://nawa.gov.pl/en/nawa/news/call-for-applications-for-the-polonista-nawa-2026-scholarship-programme-opens',false,null,false,null,true),
('x-anders-nawa','Gen. Anders NAWA (польская диаспора)','Польша','pl',array['bachelor','master','language-year'],'Бесплатное очное обучение на польском в государственных вузах + стипендия NAWA 2 000 PLN/мес (бакалавриат и магистратура, набор 2026) на весь срок обучения; возможен бесплатный подготовительный год польского языка.',null,null,null,'9 июля','07-09','03-31','Официально: Gen. Anders NAWA Scholarship Programme (Program im. gen. Andersa) — bachelor / master for Polish diaspora. Только для лиц польского происхождения (Karta Polaka или документально подтверждённые польские корни; лица с двойным польским гражданством тоже допускаются) — в Казахстане большая польская диаспора. Обучение только на польском; часть программ (лингвистика, иностранные языки) исключена.',null,'https://nawa.gov.pl/en/nawa/news/anders-nawa-the-calls-for-applications-are-open',false,null,false,null,true),
('x-kirkland','Lane Kirkland (Польша)','Польша','pl',array['research'],'9 месяцев постдипломного обучения (2 семестра курсов в польском вузе + стажировка): стипендия 22 500 PLN за программу (~2 500 PLN/мес), оплата обучения, проживания, страховки, визы, проезда, курса польского и учебных материалов (совокупно ок. 5 000 PLN/мес).',null,null,null,'1 марта','03-01','12-01','Официально: Lane Kirkland Scholarship Program (Program Stypendialny im. Lane''a Kirklanda). Казахстан в списке стран. Нужны диплом магистра, минимум 2 года опыта работы, возраст до 40 лет, польский или английский B2 (для англ. — базовый польский A1); не даёт степени, но финансирует год учёбы и стажировки.',null,'https://kirkland.edu.pl/en/scholarship-competition/the-lane-kirkland-scholarship-program/',false,null,false,null,true),
('fsv_scholars','FSV UK Scholars (Карлов университет)','Чехия','cz',array['bachelor','master'],'Единовременная выплата ок. 75 000 CZK (≈3 000 EUR) в год студентам платных англоязычных программ факультета социальных наук; освобождения от платы нет, но сумма покрывает около половины годовой платы; подавать заново каждый год.',0.3,0.3,'{"academics": 7, "language": 6.5, "budget": 3}'::jsonb,'30 апреля','04-30','02-01','Официально: FSV UK SCHOLARS Program — Faculty of Social Sciences, Charles University. Гражданство не ограничено; отбор по мотивационному эссе, рекомендации, оценкам и финансовому положению. Действует год, продление — через повторную заявку.',array['hum','bus'],'https://fsv.cuni.cz/en/admissions/scholarships-funding-and-fees/fsv-uk-scholars-program',false,null,false,null,true),
('matfyz_tuition','Matfyz Tuition Scholarships (Карлов университет)','Чехия','cz',array['bachelor','master'],'Покрытие платы за обучение: 7 100 EUR в год для студентов не из ЕС (4 200 EUR для ЕС) на весь срок — 3 года бакалавриата или 2 года магистратуры на англоязычных программах Computer Science; аналогичные схемы для математики и физики. До 6 мест на бакалавриат и 2 на магистратуру по CS.',0.25,0.25,'{"academics": 7.5, "language": 6.5, "budget": 3}'::jsonb,'30 апреля','04-30','01-15','Официально: Computer Science / Prague Mathematics / Prague Physics Tuition Fee Scholarships — Faculty of Mathematics and Physics, Charles University (Matfyz). Отдельная заявка на стипендию (CV, мотивационное письмо, 2 рекомендации) параллельно с поступлением; нельзя совмещать с другой стипендией. Мест очень мало, отбор по академическим результатам.',array['it','sci'],'https://www.mff.cuni.cz/en/admissions/scholarships/cstf-scholarships-2026',false,null,false,null,true),
('stars_phd','STARS PhD (Карлов университет)','Чехия','cz',array['phd'],'Полностью финансируемые PhD-позиции: гарантированный минимум 20 500 CZK/мес (≈800 EUR) на 4 года, фактически часто выше за счёт грантов проектов; обучение без платы.',0.2,0.95,'{"academics": 7.5, "language": 6.5, "budget": 0}'::jsonb,'30 апреля (ориентировочно)','04-30','02-19','Официально: STARS PhD Programme — Faculty of Science, Charles University. Нужен диплом магистра по естественным наукам/медицине/фармации; выбираете до 3 проектов, отбор руководителем и интервью. Открыто для всех иностранцев.',array['sci'],'https://stars-natur.cz/',false,null,false,null,true),
('x-jcmm-brno','JCMM (Брно, Чехия)','Чехия','cz',array['master','phd'],'Стипендия 7 000 CZK/мес на проживание для студентов не из ЕС, поступающих на магистратуру или PhD на чешском языке (обучение на чешском в государственных вузах бесплатное) в Masaryk University, Brno University of Technology, Mendel University или University of Veterinary Sciences Brno.',null,null,null,'31 января','01-31','12-01','Официально: JCMM Scholarship for Foreign Students (South Moravian Centre for International Mobility, Brno). Нужен очень хороший чешский; нельзя ранее учиться в чешском вузе (кроме языковых курсов) и жить в Чехии 6+ месяцев до июня года поступления. Заявка отдельно от поступления в вуз.',null,'https://www.jcmm.cz/projekt/internacionalizace_en/',false,null,false,null,true),
('debrecen_intl','University of Debrecen International','Венгрия','hu',array['bachelor','master'],'Скидка до 90% годовой платы за обучение (до 30% на медицине/стоматологии) на программах по инженерии, IT, естественным и аграрным наукам, здравоохранению и математике + медицинская страховка; размер зависит от оценок и вступительного экзамена.',0.35,0.35,'{"academics": 6.5, "language": 6, "budget": 3}'::jsonb,'15 июня','06-15','01-16','Официально: University of Debrecen International Scholarship (UD International Scholarship). Казахстан среди 100+ стран-участниц; нельзя быть уже зачисленным в венгерский вуз; только сентябрьский набор. Стипендия не покрывает проживание.',null,'https://edu.unideb.hu/page.php?id=426',false,null,false,null,true),
('corvinus_scholarship','Corvinus Scholarship (Будапешт)','Венгрия','hu',array['master'],'Полное или частичное покрытие платы за обучение (до 100% семестровой платы) для студентов платных программ; до 20 мест на каждую из трёх магистерских программ; для сохранения — ≥54 кредитов за 2 семестра и средний балл ≥3,8.',0.2,0.2,'{"academics": 7.5, "language": 6.5, "budget": 3}'::jsonb,'31 мая (ориентировочно)','05-31','11-01','Официально: Corvinus Scholarship — Corvinus University of Budapest (tuition-free places on MSc Management and Leadership, MSc Finance, International MBA). Только для самофинансируемых студентов (не Stipendium Hungaricum); стипендия не покрывает проживание. Отбор по академическим результатам, решение принимает президентский комитет.',array['bus'],'https://corvinus-university.dreamapply.com/news/new/50-full-tuition-scholarships-available-corvinus',false,null,false,null,true),
('x-slovakia-talented','Стипендии Словакии для талантливых','Словакия','sk',array['bachelor','master'],'500 EUR/мес по 10 месяцев в год: 3 года бакалавриата (15 000 EUR) или 2 года магистратуры (10 000 EUR) для иностранцев, зачисленных в государственные вузы Словакии; всего 150 мест на бакалавриат и 45 на магистратуру (квоты по регионам мира).',null,null,null,'по объявлению (регистрация ещё не открыта; approx весна–лето)',null,null,'Официально: Scholarships for talented students from abroad (Štipendiá pre talentovaných študentov zo zahraničia) — Slovak Ministry of Education / portalvs.sk. Единственный критерий отбора — результат SAT (минимум 1100); не подходит тем, кто жил в Словакии с 2021 г. или уже учился там. PhD не финансируется; обучение на словацком в госвузах бесплатное, англоязычные программы платные.',null,'https://scholarships.portalvs.sk/',false,null,false,null,true),
('aubg','AUBG (Болгария)','Болгария','bg',array['bachelor'],'9 полных стипендий (100% tuition) AUBG Distinguished Scholarship; AUBG Funded Scholarship до 40% платы автоматически по академическим данным; донорские стипендии 2 000–4 800 EUR/год, в т.ч. «Scholarships for International Students» для Восточной Европы и Центральной Азии и Huwiler/Khamatova для студентов из Центральной Азии (по нужде).',0.3,0.3,'{"academics": 7, "language": 6.5, "budget": 3}'::jsonb,'15 января','01-15','09-01','Официально: American University in Bulgaria (AUBG) — Distinguished, AUBG Funded and Donor-Funded Scholarships. Все заявители автоматически рассматриваются на merit-стипендии; полных стипендий всего 9, для них нужны высокие оценки и тесты + лидерство. Для need-based нужны финансовые документы; лучшие шансы при подаче до 15 января.',null,'https://www.aubg.edu/admissions/bachelors/cost-aid/scholarships/',false,null,false,null,true),
('greece_mfa_ug','МИД Греции — бакалавриат','Греция','gr',array['bachelor'],'50 полных стипендий: 650 EUR/мес, освобождение от платы за обучение, бесплатные учебники, при необходимости бесплатный год изучения греческого; на весь срок бакалавриата + 2 года.',0.25,0.85,'{"academics": 6, "language": 3, "budget": 2}'::jsonb,'8 сентября (ориентировочно)','09-08','07-01','Официально: Hellenic Ministry of Foreign Affairs — Undergraduate Scholarships in Greece for foreign nationals. Казахстан прямо указан в списке 33 стран; подача только через посольство/консульство Греции; нужна справка о постоянном проживании за пределами Греции ≥5 лет. Обучение на греческом — сначала языковой год.',null,'https://www.mfa.gr/missionsabroad/en/luxembourg-en/news/undergraduate-scholarships-in-greece-offered-by-the-hellenic-ministry-of-foreign-affairs-for-the-academic-year-20252026.html',false,null,true,null,true),
('vu_waiver','Vilnius University — освобождение от платы','Литва','lt',array['master','bachelor'],'5 полных освобождений от платы за обучение на англо-/русскоязычных магистерских программах для выдающихся кандидатов не из ЕС; полное освобождение на BA Politics of Global Challenges и MA Eastern European and Russian Studies (IIRPS); Faculty of Law — 50–100% платы на International and European Law для граждан Казахстана и ещё 6 стран.',0.25,0.25,'{"academics": 7, "language": 6.5, "budget": 3}'::jsonb,'1 июня (ориентировочно)','06-01','11-01','Официально: Vilnius University — Tuition fee waivers for non-EU master''s applicants + Faculty of Law special scholarship. Казахстан прямо назван в списке стран для юридической стипендии. Освобождения покрывают только обучение, не проживание; количество мест минимально, отбор по академическим результатам.',null,'https://admissions.vu.lt/all-news/study-without-financial-burden-vilnius-university-offers-a-variety-of-funding-opportunities-1',false,null,false,null,true),
('vilniustech','VILNIUS TECH (Литва)','Литва','lt',array['bachelor','master'],'100% освобождение от платы за обучение на весь срок (4 года бакалавриата / 2 года магистратуры при отсутствии задолженностей) для кандидатов с ≥80% максимальной оценки; 50% или 25% — при ≥70%. Проживание не покрывается.',0.35,0.35,'{"academics": 6.5, "language": 6, "budget": 3}'::jsonb,'20 апреля','04-20','11-01','Официально: VILNIUS TECH (Vilnius Gediminas Technical University) — Tuition-free and partial (50%/25%) scholarships for international students. Отдельная заявка через apply.vilniustech.lt с мотивационным письмом (1 000–4 000 знаков) и 2 академическими рекомендациями; английский B2. Инженерия, IT, архитектура, бизнес.',array['eng','it','bus'],'https://vilniustech.lt/en/international-students/full-time-students/scholarships/',false,null,false,null,true),
('ktu_waiver','KTU Каунас — освобождение от платы','Литва','lt',array['master'],'Полное или частичное освобождение от платы за обучение (плата 4 690–7 116 EUR/год) для кандидатов с сильными академическими результатами и мотивацией; все подавшие заявку рассматриваются автоматически.',0.35,0.35,'{"academics": 6.5, "language": 6, "budget": 3}'::jsonb,'1 июня','06-01','10-15','Официально: Kaunas University of Technology (KTU) — Full or partial tuition fee waiver for international master''s applicants. Отдельная заявка не нужна — отбор из всех поступающих; результаты в середине июля. Покрывает только обучение; для полного пакета можно параллельно подать на литовскую госстипендию.',array['eng','it','bus','sci'],'https://admissions.ktu.edu/master/',false,null,false,null,true),
('tlu_waiver','Tallinn University — освобождение от платы','Эстония','ee',array['bachelor','master'],'Два 100%-х освобождения от платы в год в School of Governance, Law and Society (2 лучших по рейтингу приёма); 50–100% скидка со 2-го семестра на всех программах Baltic Film, Media and Arts; по два-четыре 50%-х освобождения на Liberal Arts in Humanities и Estonian Studies; 25–50% на Educational Innovation & Leadership.',0.25,0.25,'{"academics": 7, "language": 6.5, "budget": 3}'::jsonb,'15 апреля (ориентировочно)','04-15','01-02','Официально: Tallinn University — Tuition waivers for international students (School of Governance, Law and Society; Baltic Film, Media and Arts; Humanities). Освобождения назначаются по результатам вступительных испытаний, отдельная заявка не нужна; проживание не покрывается. Для сохранения скидки нужен минимальный GPA и очная форма.',array['hum','law','art'],'https://www.tlu.ee/en/scholarships',false,null,false,null,true),
('x-ozyegin','Özyeğin University (Турция)','Турция','tr',array['bachelor'],'Скидки 40%, 50%, 60% (по примерам вуза) от платы 25 000 USD/год по академическим достижениям, мотивационному письму и квотам программ; все поступающие автоматически рассматриваются на стипендию.',null,null,null,'rolling (несколько раундов; approx)',null,'01-15','Официально: Özyeğin University — Scholarships for international undergraduate applicants. Отдельная заявка не нужна; полных стипендий на этой странице нет — реалистично 40–60% платы. Общежитие и проживание не покрываются.',null,'https://admissions.ozyegin.edu.tr/en/tuition-fees-and-scholarship/',false,null,false,null,true),
('x-ibn-haldun','Ibn Haldun University (Турция)','Турция','tr',array['master','phd'],'100% освобождение от платы за обучение (OGB) + merit-стипендия 23 500 TL/мес в магистратуре и 18 500 TL/мес в докторантуре (BAB); ÜBB — 18 000 TL/мес только для PhD; в рамках квот программ (набор 2026–2027).',null,null,null,'по программам (обычно весна–лето; approx)',null,null,'Официально: Ibn Haldun University — Graduate scholarships: Full Tuition Exemption (OGB), Merit Scholarship (BAB), Outstanding Achievement (ÜBB). Стипендии распределяются по квотам и бюджету каждой программы; на странице нет ограничений по гражданству, но иностранным кандидатам стоит подтвердить условия у приёмной комиссии. Вуз частный, профиль — социальные науки.',null,'https://apply.ihu.edu.tr/en/how-do-i-get-a-tuition-fee-exemption-or-a-scholarship',false,null,false,null,true),
('heydar_aliyev','Грант Гейдара Алиева (Азербайджан)','Азербайджан','az',array['bachelor','master','phd'],'100 грантов в год: полная плата за обучение и языковой подготовительный курс, авиабилеты в Баку и обратно раз в год, стипендия 800 AZN/мес (≈470 USD, 10 мес в году), 200 AZN/год на медицину, виза и регистрация.',0.18,0.9,'{"academics": 7, "language": 3, "budget": 0}'::jsonb,'15 апреля','04-15','02-16','Официально: Heydar Aliyev International Education Grant Program (Government of Azerbaijan). Открыт для граждан стран ОИС и Движения неприсоединения — Казахстан член ОИС. Обязательна официальная номинация госорганами своей страны; возраст до 35 (бакалавриат), 40 (магистратура), 45 (PhD); IELTS 5.0/5.5 для англоязычных программ.',null,'https://studyinazerbaijan.edu.az/heydar-aliyev-international-education-grant-program',false,null,true,null,true),
('x-khazar','Khazar University (Азербайджан)','Азербайджан','az',array['bachelor','master','phd'],'Освобождение от 25%, 50% или 75% платы за обучение на бакалавриате, магистратуре и PhD; Excellence Scholarship — 100% платы на год для магистров/PhD (продлевается по успеваемости); Nailekhanim Foundation — одна полная стипендия для женщин в магистратуре (GPA ≥3,7).',null,null,null,'rolling; Nailekhanim — до 30 июня',null,null,'Официально: Khazar University — Merit-based scholarships for international students (25%/50%/75%) and Excellence Scholarship. Все поступающие рассматриваются автоматически, решение приходит вместе с офером; проживание не покрывается. Частный вуз в Баку, обучение на английском.',null,'https://international.khazar.org/en/page/international-scholarship-program',false,null,false,null,true),
('aua_armenia','American University of Armenia (AUA)','Армения','am',array['bachelor','master'],'Международная merit-стипендия покрывает до 50% международной платы за обучение (по результатам вступительных тестов, заявки и эссе); дополнительно need-based tuition assistance, рассрочка и work-study до 20 ч/нед.',0.3,0.3,'{"academics": 6.5, "language": 6, "budget": 3}'::jsonb,'30 июня','06-30','11-01','Официально: American University of Armenia (AUA) — International Scholarship (merit) and Need-Based Tuition Assistance. Нужна отдельная заявка на стипендию в Office of Financial Aid; покрывает не более половины платы, проживание не входит. Аккредитован в США (WASC), обучение на английском.',null,'https://finaid.aua.am/international-scholarships/',false,null,false,null,true),
('x-auca','AUCA (Бишкек)','Кыргызстан','kg',array['bachelor'],'Стипендии до 90% платы за обучение по академическим результатам и финансовой нужде; около 84% студентов бакалавриата получают помощь. Доступна поступающим и продолжающим студентам из Кыргызстана и других стран Центральной Азии.',null,null,null,'вместе с приёмной кампанией (весна–лето; approx)',null,null,'Официально: American University of Central Asia (AUCA, Bishkek) — Merit- and need-based financial aid. Финансовая помощь прямо адресована студентам из стран Центральной Азии, включая Казахстан; требуется заявка на financial aid с подтверждением доходов семьи. Диплом AUCA признан Bard College (США).',null,'https://www.auca.kg/en/soc_undergrad_admissions/',false,null,false,null,true),
('uca_naryn','University of Central Asia (UCA)','Кыргызстан','kg',array['bachelor'],'Приём по заслугам без учёта платёжеспособности: «никому не отказывают по финансовым причинам, а после зачисления финансовая помощь гарантирована»; пакет по нужде покрывает плату за обучение, проживание и питание в кампусе (доля зависит от дохода семьи).',0.4,0.9,'{"academics": 6, "language": 5.5, "budget": 2}'::jsonb,'14 февраля (ориентировочно)','02-14','10-01','Официально: University of Central Asia (UCA, Naryn / Khorog) — Undergraduate admission with guaranteed financial aid. Вуз Ага-хана для Центральной Азии (кампусы Нарын, Хорог); нужны SAT/внутренний тест и отдельная заявка на financial aid (до апреля). Полное покрытие — только при подтверждённой финансовой нужде.',null,'https://admissions.ucentralasia.org/',false,null,false,null,true),
('osce_academy','OSCE Academy (Бишкек)','Кыргызстан','kg',array['master'],'Обучение бесплатное (полный tuition waiver всем зачисленным) + ежемесячная стипендия на проживание в Бишкеке (в т.ч. 450 EUR на жильё); годичные англоязычные MA-программы.',0.2,0.95,'{"academics": 7.5, "language": 6.5, "budget": 0}'::jsonb,'1 апреля (ориентировочно)','04-01','01-15','Официально: OSCE Academy in Bishkek — MA in Politics and Security / Economic Governance and Development / Human Rights and Sustainability. Только для граждан государств-участников ОБСЕ (Казахстан входит) и Афганистана; нужен IELTS 6.5 / TOEFL 90 или внутренний экзамен по английскому; работать полный день во время учёбы нельзя.',array['hum','law','bus'],'https://osce-academy.net/en/admission/faq/',false,null,false,null,true),
('manas_kg','Университет «Манас» (Кыргызстан)','Кыргызстан','kg',array['bachelor','master','phd'],'Бесплатное обучение для всех зачисленных (включая иностранцев) + merit-стипендия: не менее 7 200 сом/мес в магистратуре и 9 600 сом/мес в докторантуре; бакалавриат — бесплатно по результатам вступительного экзамена университета.',0.35,0.7,'{"academics": 6, "language": 3, "budget": 2}'::jsonb,'10 июля','07-10','06-01','Официально: Kyrgyz-Turkish Manas University (Кыргызско-Турецкий университет «Манас») — tuition-free study + merit stipend. Языки обучения — кыргызский и турецкий (без сертификата нужно сдать языковой экзамен или пройти подготовительный год); диплом должен быть признан в КР/Турции. Стипендия небольшая, но обучение полностью бесплатное.',null,'https://manas.edu.kg/en/news/7970',false,null,true,null,true),
('x-cau-tashkent','Central Asian University (Ташкент)','Узбекистан','uz',array['bachelor'],'Merit-based Scholarship 25%, 50% или 100% платы за обучение для лучших абитуриентов из Узбекистана, Казахстана, Кыргызстана, Таджикистана и Туркменистана; дополнительно CAU Excellence (до 100%), Academic Excellence (25–100% для продолжающих), English Proficiency (10–20%), Early Bird (10%).',null,null,null,'по раундам приёма (весна–лето; approx)',null,null,'Официально: Central Asian University (CAU, Tashkent) — Merit-Based Scholarship for students from Central Asia (25/50/100%). Казахстан прямо указан в списке стран для merit-стипендии; нужны сильные оценки и, как правило, SAT/IELTS. Проживание не покрывается; частный вуз в Ташкенте с обучением на английском.',null,'https://centralasian.uz/scholarshipsfor2026entry',false,null,false,null,true),
('x-jasso-honors','JASSO Honors (Япония)','Япония','jp',array['bachelor','master','phd','language-year'],'Ежемесячная стипендия 48 000 JPY (бакалавриат/магистратура/PhD) или 30 000 JPY (языковые школы) на 12 месяцев (апр–март) или 6 месяцев (окт–март). Обучение не покрывается.',null,null,null,'через вуз после зачисления (обычно апрель/октябрь); есть резервирование через…',null,null,'Официально: Monbukagakusho Honors Scholarship for Privately-Financed International Students (JASSO). Подаётся только через международный офис японского вуза после зачисления, квота на вуз ограничена. Нужен JLPT N2+/EJU 200+ или английский B2; доход спонсора < 5 млн JPY/год. Можно «забронировать» стипендию, сдав EJU до приезда.',null,'https://www.jasso.go.jp/en/ryugaku/scholarship_j/shoreihi/about.html',false,null,false,null,true),
('yoneyama','Rotary Yoneyama (Япония)','Япония','jp',array['bachelor','master','phd'],'100 000 JPY/мес (бакалавриат) или 140 000 JPY/мес (магистратура и докторантура), плюс до 250 000 JPY на дорогу в Японию. Обучение не покрывается.',0.12,0.12,'{"academics": 7.5, "language": 5.5, "budget": 3}'::jsonb,'31 октября','10-31','10-01','Официально: Rotary Yoneyama Memorial Scholarship (Overseas Candidates) / ロータリー米山記念奨学金. Нужен JLPT N3 или выше и уже полученное (или подтверждённое) зачисление в японский вуз; research students не подходят. Стипендиат должен прибыть в Японию до начала выплат, иначе теряет право.',null,'https://www.rotary-yoneyama.or.jp/english/overseas',false,null,false,null,true),
('honjo','Honjo International (Япония)','Япония','jp',array['master','phd'],'210 000 JPY/мес при программе 1–2 года, 190 000 JPY/мес при 3 годах, 160 000 JPY/мес при 4–5 годах; выплачивается весь срок обучения. Обучение не покрывается.',0.06,0.06,'{"academics": 8.5, "language": 6, "budget": 3}'::jsonb,'31 октября (ориентировочно)','10-31','09-01','Официально: Honjo International Scholarship Foundation — Scholarship for Foreign Students. Всего ~5 стипендий на цикл, конкурс очень высокий. Нужно уже быть зачисленным (или иметь допуск) в магистратуру/докторантуру японского вуза; требуется 2-минутное видео о своём исследовании и очное собеседование в Токио.',null,'https://www.hisf.or.jp/en/scholarship/foreigner/',false,null,false,null,true),
('kyoto_iup','Kyoto iUP (Япония)','Япония','jp',array['bachelor'],'Полное освобождение от вступительного взноса и полное/частичное освобождение от платы за обучение на 4,5 года; до 120 000 JPY/мес на 6-месячном подготовительном курсе; далее merit-стипендии от компаний-партнёров.',0.15,0.85,'{"academics": 8, "language": 6.5, "budget": 0}'::jsonb,'3 декабря','12-03','11-02','Официально: Kyoto University International Undergraduate Program (Kyoto iUP). Программа 6 мес. подготовки + 4 года бакалавриата; японский учится с нуля, но лекции старших курсов на японском. Все документы на английском; предварительный скрининг соответствия требованиям; отбор по документам и собеседованию.',null,'https://www.iup.kyoto-u.ac.jp/apply/',false,null,false,null,true),
('x-tohoku-fgl','Tohoku FGL President Fellowship','Япония','jp',array['bachelor'],'President Fellowship: полное или частичное освобождение от платы за обучение + 267 900 JPY за семестр до 4 лет (~535 800 JPY/год). Отдельно 8 мест MEXT по рекомендации вуза (не включено).',null,null,null,'январь (последний цикл — приём в январе, зачисление в октябре); даты 2027 не…',null,null,'Официально: Tohoku University Future Global Leadership (FGL) Program — President Fellowship. Три англоязычных бакалавриата: молекулярная химия (AMC), механика и аэрокосмос (IMAC-U), морская биология (AMB). Нужны стандартизированные тесты по математике/физике/химии/биологии (SAT/A-level/IB) и TOEFL iBT 79+ / IELTS 6.0+; число фелоушипов не публикуется.',null,'https://www.insc.tohoku.ac.jp/english/degree/undergraduate-english-future-global-leadership-program/',false,null,false,null,true),
('nagoya_g30','Nagoya G30 (Япония)','Япония','jp',array['bachelor'],'Полное освобождение от платы за обучение на 4 года + стипендия 500 000 JPY суммарно за 4 года. Также автоматическое рассмотрение на MEXT (University Recommendation: 117 000 JPY/мес + перелёт).',0.2,0.2,'{"academics": 7.5, "language": 6.5, "budget": 3}'::jsonb,'19 ноября','11-19','11-02','Официально: Nagoya University Global 30 (G30) Undergraduate Scholarship. 10 англоязычных бакалавриатов, японский не требуется при поступлении. Отдельной заявки на стипендию нет — рассматриваются все поступающие (нужно приложить форму); учитываются успеваемость, внеучебная активность и финансовая потребность.',null,'https://admissions.g30.nagoya-u.ac.jp/studentlife/scholarships/',false,null,false,null,true),
('x-nagoya-fellowship','Nagoya Frontier Fellowship (PhD)','Япония','jp',array['phd'],'Исследовательская стипендия 180 000–200 000 JPY/мес + грант на исследования 250 000–500 000 JPY/год для докторантов.',null,null,null,'через graduate school после поступления в докторантуру; сроки по школам',null,null,'Официально: Nagoya University Interdisciplinary Frontier Fellowship (NU Research Support Projects). Фелоушип для докторантов, отбор проводит соответствующая graduate school Нагойского университета; открыт всем гражданствам, но конкурс внутренний. Не покрывает плату за обучение напрямую.',null,'https://admissions.g30.nagoya-u.ac.jp/studentlife/scholarships/',false,null,false,null,true),
('x-keio-dfa','Keio Design the Future Award','Япония','jp',array['master','phd'],'Полная плата за обучение и сборы Keio + ежемесячная стипендия + единовременный подготовительный грант (включая субсидию на перелёт). Точные суммы не публикуются.',null,null,null,'до зачисления, только по номинации факультета; дат нет',null,null,'Официально: Keio University Design the Future Award for International Students. Заявиться самому нельзя — кандидатов номинируют graduate schools Keio (например SDM) среди сильнейших поступающих, и подать могут только те, с кем связались напрямую. Ультра-выборочный, число мест не раскрывается.',null,'https://www.sdm.keio.ac.jp/en/admission/financialaid.html',false,null,false,null,true),
('x-apu-ug','Ritsumeikan APU (бакалавриат)','Япония','jp',array['bachelor'],'Скидка 30/50/65/80/100% с платы за обучение на весь срок; при 100% — 1 455 000 JPY/год (студент платит 0), при 80% — 1 164 000 JPY/год. Проживание не покрывается.',null,null,null,'несколько раундов в год (набор на апрель и сентябрь 2027); ранняя подача повы…',null,null,'Официально: Ritsumeikan APU Tuition Reduction Scholarship (Undergraduate). Отдельной заявки нет — отметка в заявлении на поступление; решение по документам, записанному видеоинтервью и финансовому положению семьи. Продление ежегодно при выполнении требований по GPA и кредитам.',null,'https://admissions.apu.ac.jp/costs_scholarships/before_enrollment/',false,null,false,null,true),
('x-apu-grad','Ritsumeikan APU (магистратура)','Япония','jp',array['master'],'Скидка 30/50/65/80/100% с платы за обучение на стандартный срок программы; годовая плата до 1 455 000 JPY (GSA) и до 2 000 000 JPY (GSM/MBA) при 0%.',null,null,null,'по расписанию набора 2027 (несколько раундов на апрель/сентябрь)',null,null,'Официально: Ritsumeikan APU Tuition Reduction Scholarship (Graduate: GSA / GSM MBA). Решение принимается по документам заявки вместе с решением о приёме и не пересматривается; для MBA сильно влияет GMAT/GRE. Стипендия снимается при получении внешнего полного финансирования.',null,'https://admissions.apu.ac.jp/graduate/cost/tuition_reduction_scholarship/',false,null,false,null,true),
('gist_ug','GIST для иностранцев (Корея)','Корея','kr',array['bachelor'],'Полная плата за обучение + освобождение от вступительного взноса, 530 000 KRW/мес (питание 270 000 + стипендия 130 000 + надбавка иностранцу 130 000), общежитие (двухместное), билет в одну сторону в Корею.',0.2,0.95,'{"academics": 8, "language": 6.5, "budget": 0}'::jsonb,'15 марта (ориентировочно)','03-15',null,'Официально: GIST International Undergraduate Admission — Full Scholarship. Только для иностранцев, оба родителя которых не корейцы. Отбор по SAT/AP/IB/ACT, аттестату и рекомендациям + опциональное телефонное интервью в мае; только STEM-направления.',array['sci','eng','it'],'https://service.gist.ac.kr/applicationGuide/Brochure%20of%20International%20Undergraduate%20Admission.pdf',false,null,false,null,true),
('x-unist-ug','UNIST для иностранцев (Корея)','Корея','kr',array['bachelor'],'Все первокурсники — 100% платы за обучение в 1-м семестре; далее 100% при GPA ≥2.7 (50% при ≥2.0). Стипендия на жизнь: Gold 630 000 KRW/мес, Silver 330 000, Dream 130 000 (с 2-разовым питанием) + возмещение страховки 75 000 KRW/мес.',null,null,null,'приём на осень 2027 по Fall 2027 Guidelines (обычно осень–зима, approx)',null,null,'Официально: UNIST International Undergraduate Scholarships (Tuition + Gold/Silver/Dream living scholarships). Тип стипендии на проживание (Gold/Silver/Dream) назначается UNIST при зачислении по результатам отбора; продление зависит от GPA и 12+ кредитов за семестр. STEM и бизнес-направления.',null,'https://admu-intl.unist.ac.kr/admission-eng/life/scholarships.do',false,null,false,null,true),
('x-kdi-gas','KDI School GAS (Корея)','Корея','kr',array['master','phd'],'Полное освобождение от платы за обучение + ежемесячная стипендия для большинства стипендиатов (сумма на сайте не указана); для остальных — частичные стипендии.',null,null,null,'весенний набор: подача летом (скрининг документов 18 авг – 7 сент 2026); осен…',null,null,'Официально: KDI School Global Ambassador Scholarship (GAS). Приоритет гражданам стран-получателей ODA — Казахстан входит в список DAC, но приоритет не гарантия. Программы MPP/MDP/MPM; есть собеседование; магистратура ~1,5 года, PhD только с весеннего набора.',null,'https://www.kdischool.ac.kr/menu.es?mid=a40203000000',false,null,false,null,true),
('korea_univ_grad','Korea University Global Leader','Корея','kr',array['master','phd'],'Type A: 100% платы за обучение + вступительный взнос + 500 000 KRW/мес × 4 месяца; Type B (гуманитарные/социальные): 60% платы; Type C (естественные/инженерные): 65% платы. Действует на 1-й семестр, далее пересмотр по GPA.',0.3,0.3,'{"academics": 7.5, "language": 6.5, "budget": 3}'::jsonb,'10 сентября (ориентировочно)','09-10','09-01','Официально: Korea University Graduate School — Global Leader Scholarship (Type A) и стипендии Type B/C. Заявка на стипендию подаётся вместе с заявлением на поступление; нужны рекомендация кафедры и согласие декана. Для Type A — GPA ≥4.0/4.5 и TOEFL iBT 90+/IELTS 7.0+/TOPIK 6; нельзя совмещать с GKS.',null,'https://graduate2.korea.ac.kr/scholarship/scholarships.html',false,null,false,null,true),
('x-hanyang-hiea','Hanyang HIEA (Корея)','Корея','kr',array['bachelor','master'],'Скидка 70%, 50% или 30% с платы за обучение на один семестр по результатам оценки; продление — повторной заявкой каждый семестр.',null,null,null,'5 марта','03-05','03-01','Официально: Hanyang International Excellence Awards (HIEA). Подаётся уже после зачисления, каждый семестр заново; обязателен сертификат TOPIK, GPA ≥3.0 за прошлый семестр и медстраховка. Нельзя совмещать с другими стипендиями (кроме GKS).',null,'https://www.hanyang.ac.kr/web/eng/scholarships1',false,null,false,null,true),
('x-skku-ug','SKKU Samsung Global (Корея)','Корея','kr',array['bachelor'],'Samsung Global Sungkyun: 100% платы 4 года + 570 000 KRW/мес на жизнь + общежитие + менторство. Admission Scholarship: 10–100% платы за 1-й семестр автоматически по итогам отбора; 100%/50% за 1-й семестр при IELTS 8.0/7.0 (TOEFL 110/95) или TOPIK 6/5; далее merit 30–70% по рейтингу.',null,null,null,'по расписанию набора иностранцев (весна/осень 2027); даты не опубликованы',null,null,'Официально: Sungkyunkwan University (SKKU) — Samsung Global Sungkyun Scholarship и стипендии для иностранных первокурсников. Samsung Global Sungkyun и Global Leader Scholarship (50% на 4 года) — только по номинации вуза, нужно держать GPA 3.5+. Автоматические стипендии покрывают только 1-й семестр, дальше зависит от рейтинга.',null,'https://admission-global.skku.edu/eng/grad/scholarship_undergrad.html',false,null,false,null,true),
('sutd_rainmaker','SUTD Rainmaker (Сингапур)','Сингапур','sg',array['bachelor'],'Субсидированная плата за обучение (после MOE Tuition Grant) до 4 лет + пособие S$10 000/год (S$5 000 за семестр) + до S$5 000 на зарубежную программу от 4 недель. Без бонда по стипендии.',0.15,0.15,'{"academics": 8.5, "language": 6.5, "budget": 0}'::jsonb,'2 марта (ориентировочно)','03-02','01-02','Официально: SUTD Rainmaker (International) Scholarship. Для иностранцев и PR; нужны сильные A-level/IB/эквивалент, лидерство и общественная активность. Учтите: сама MOE Tuition Grant подразумевает обязательство отработать 3 года в сингапурской компании.',array['eng','it'],'https://www.sutd.edu.sg/admissions/undergraduate/scholarship/sutd-administered/sutd-rainmaker-scholarship-intl/',false,null,false,null,true),
('x-ntu-npgs','NTU NPGS PhD (Сингапур)','Сингапур','sg',array['phd'],'Для иностранцев: стипендия S$4 300/мес + полная плата за обучение + до S$5 000/год на конференции + S$500/год на книги + S$1 500 на IT + S$600 на диссертацию + приоритет в общежитии; до 4 лет.',null,null,null,'период подачи на 2027/28 будет объявлен (обычно осень–зима, approx)',null,null,'Официально: Nanyang President''s Graduate Scholarship (NPGS), NTU Singapore. Нужен бакалавриат с Honours (Highest Distinction) или эквивалент; иностранцы обязаны участвовать в Graduate Assistantship Programme (преподавание/лабораторные). Ежегодное продление по прогрессу.',null,'https://www.ntu.edu.sg/admissions/graduate/financialmatters/scholarships/npgs',false,null,false,null,true),
('hku_ps','HKU Presidential PhD','Гонконг','hk',array['phd'],'Год 1 до ~HK$445 800 (далее ~HK$428 300/год): стипендия HK$28 700/мес, cash award HK$40 000 (затем HK$20 000/год), освобождение от composition fee HK$49 500/год, HK$14 400/год на поездки, гарантированное общежитие в 1-й год.',0.08,0.08,'{"academics": 9, "language": 7, "budget": 0}'::jsonb,'1 декабря','12-01','09-01','Официально: HKU Presidential PhD Scholar Programme (HKU-PS). Отдельной заявки нет — рассматриваются все поступающие на full-time PhD; шорт-лист приглашают на интервью. Рекомендуется параллельно подавать на HK PhD Fellowship Scheme; конкурс очень высокий.',null,'https://gradsch.hku.hk/prospective_students/fees_scholarships_and_financial_support/hku_presidential_phd_scholar_programme',false,null,false,null,true),
('x-anu-chancellors','ANU Chancellor''s International','Австралия','au',array['bachelor','master'],'Скидка 25% или 50% с платы за обучение на весь срок программы (бакалавриат или coursework-магистратура).',null,null,null,'отдельной заявки нет — по срокам приёма ANU на 2027 (несколько раундов)',null,null,'Официально: ANU Chancellor''s International Scholarship. Все иностранные абитуриенты рассматриваются автоматически по рейтингу оценок, переведённых в общую шкалу; число стипендий ограничено, доля 50% — для сильнейших. Проживание и перелёт не покрываются.',null,'https://study.anu.edu.au/scholarships/find-scholarship/anu-chancellors-international-scholarship',false,null,false,null,true),
('x-uq-excellence','UQ International Excellence','Австралия','au',array['bachelor','master'],'Скидка 25% с платы за обучение каждый семестр на весь срок программы (бакалавриат и coursework-магистратура, все направления).',null,null,null,'отдельной заявки нет — по срокам приёма UQ на 2027',null,null,'Официально: UQ International Excellence Scholarship. Автоматический отбор среди получивших offer по конкурсному баллу; нельзя совмещать с другой стипендией UQ или полным внешним спонсорством. Покрывает лишь четверть стоимости — остальное и проживание за свой счёт.',null,'https://scholarships.uq.edu.au/scholarship/uq-international-excellence-scholarship',false,null,false,null,true),
('x-adelaide-excellence','Adelaide Academic Excellence','Австралия','au',array['bachelor','master'],'Скидка 50% с платы за обучение (coursework-программы). Также автоматические: Emerging Leaders Award 25%, Merit Scholarship 15%.',null,null,null,'по срокам приёма на 2027; для 50% нужна отдельная форма заявки',null,null,'Официально: Adelaide Academic Excellence Scholarship (Adelaide University, international). С 2026 объединённый Adelaide University (бывш. University of Adelaide + UniSA). Для 50% нужен средний балл уровня High Distinction и отдельная заявка; 25%/15% назначаются автоматически при подаче на программу.',null,'https://adelaide.edu.au/study/scholarships/international-students-scholarships/',false,null,false,null,true),
('x-deakin-vc','Deakin Vice-Chancellor''s','Австралия','au',array['bachelor','master'],'100% или 50% платы за обучение на стандартный срок программы + программа Professional Excellence + приоритетный доступ к кампусному жилью (за свой счёт).',null,null,null,'не позднее чем за 1 месяц до начала триместра (T1 ~ февраль, T2 ~ июнь, T3 ~…',null,null,'Официально: Deakin Vice-Chancellor''s International Scholarship. Нужно ≥85% средний балл аттестата (IB 32+) или ≥80% в бакалавриате; отдельная форма, эссе 300 слов и 2 рекомендации про лидерство/общественную работу. Только coursework, не для Doctor of Medicine; реальный порог выше минимума.',null,'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-vice-chancellors-international-scholarship',false,null,false,null,true),
('griffith_vc','Griffith Vice Chancellor''s','Австралия','au',array['bachelor','master'],'Скидка 50% с платы за обучение на весь срок программы (coursework, бакалавриат и магистратура) при сохранении GPA ≥5.5/7.',0.2,0.2,'{"academics": 7.5, "language": 6.5, "budget": 5}'::jsonb,'28 ноября','11-28',null,'Официально: Griffith Vice Chancellor''s International Scholarship. Сначала нужно получить Letter of Offer, затем подать заявку на стипендию с транскриптами и мотивационным письмом; порог GPA 6.0/7 (или эквивалент). Не для граждан Австралии/НЗ.',null,'https://www.griffith.edu.au/international/scholarships-finance/scholarships/vice-chancellors-international-scholarship',false,null,false,null,true),
('x-australia-rtp','Australia RTP (PhD)','Австралия','au',array['phd','research'],'Покрытие платы за обучение (fee offset) + стипендия на проживание (базовая ставка объявляется правительством к 1 октября ежегодно; сумма на 2027 на странице не указана) + пособия на сопутствующие расходы (переезд, страховка и т.п.).',null,null,null,'по вузам (для старта в след. году обычно авг–окт, approx)',null,null,'Официально: Australian Government Research Training Program (RTP) Scholarship. Государственная схема для PhD и research master, открыта иностранцам, но распределяется каждым университетом по своему конкурсу — подавать нужно в вуз (можно в несколько). Обычно требуется согласие научного руководителя и сильный research proposal.',null,'https://www.education.gov.au/research-block-grants/research-training-program',false,null,false,null,true),
('otago_phd','Otago Doctoral (Новая Зеландия)','Новая Зеландия','nz',array['phd'],'NZ$34 128/год стипендия + освобождение от платы за обучение по ставке для домашних студентов на 36 месяцев (без student services fee и страховки). До 153 стипендий в год.',0.25,0.25,'{"academics": 8, "language": 6.5, "budget": 0}'::jsonb,'1 марта','03-01',null,'Официально: University of Otago Doctoral Scholarship. Открыта иностранцам (PhD-иностранцы в НЗ платят по домашней ставке); заявка через eVision вместе с заявлением в докторантуру и оценкой кафедры. Вуз сейчас пересматривает схему — проверяйте актуальные условия.',null,'https://www.otago.ac.nz/study/scholarships/database/university-of-otago-doctoral-scholarship',false,null,false,null,true),
('knight_hennessy','Knight-Hennessy (Stanford)','США','us',array['master','phd'],'Полное покрытие tuition и сборов на срок до 3 лет любой full-time graduate-программы Stanford (MBA, MS, PhD, JD, MD и др.) + стипендия на проживание и учебные расходы (сумма на сайте не указана) + ежегодный авиабилет + разовое пособие на переезд.',0.04,0.95,'{"academics": 9.5, "language": 8, "budget": 0}'::jsonb,'6 октября','10-06',null,'Официально: Knight-Hennessy Scholars (Stanford University). Граждане всех стран. Первый бакалавр должен быть получен не ранее января 2020 (для когорты 2027). Нужно параллельно поступить в graduate-программу Stanford; крайне высокий конкурс (~1–2%).',null,'https://knight-hennessy.stanford.edu/admission/preparing-your-applications/application-deadlines',false,null,false,null,true),
('robertson','Robertson Scholars (Duke / UNC)','США','us',array['bachelor'],'8 семестров: полное tuition, проживание и питание, большинство обязательных сборов; финансирование до 3 летних программ; средства на конференции и 2 семестра обучения за рубежом. ~25 первокурсников в год.',0.03,0.95,'{"academics": 9.5, "language": 8.5, "budget": 0, "sat": 7}'::jsonb,'15 ноября','11-15','08-15','Официально: Robertson Scholars Leadership Program (Duke University / UNC Chapel Hill). Программа прямо принимает заявки от международных абитуриентов (единая анкета для всех). Отдельная заявка в Robertson + поступление в Duke или UNC; интервью финалистов. Студент сам должен обеспечить визу.',null,'https://robertsonscholars.org/apply/high-school-students/',false,null,false,null,true),
('emory_scholars','Emory Scholars (США)','США','us',array['bachelor'],'Merit-стипендии от частичных до полного tuition (у топ-уровня — полное tuition, проживание и питание), возобновляемые на 8 семестров.',0.04,0.04,'{"academics": 9.5, "language": 8.5, "budget": 0, "sat": 7}'::jsonb,'15 ноября','11-15',null,'Официально: Emory University Scholar Programs (Woodruff, Emory Scholars и др.). «Все студенты независимо от гражданства» рассматриваются. Достаточно ответить «да» на вопрос о Scholar Programs в заявке до 15 ноября; ~175–200 финалистов из ~10 000, финалисты приезжают в кампус в марте.',null,'https://apply.emory.edu/financial-aid/scholar-program.html',false,null,false,null,true),
('washu_scholars','WashU Signature Scholars','США','us',array['bachelor'],'Полное tuition + стипендия либо половина tuition (жильё не покрывается), на 4 года.',0.04,0.04,'{"academics": 9.5, "language": 8.5, "budget": 0, "sat": 7}'::jsonb,'4 января','01-04',null,'Официально: WashU Signature Scholar Programs — Annika Rodriguez Scholars / Danforth Scholars (Washington University in St. Louis). Иностранцы допускаются только к программам Rodriguez и Danforth (Ervin — только для граждан/резидентов США). Нужны короткие эссе через портал Pathway и рекомендации; финалисты — интервью в марте.',null,'https://scholars.washu.edu/about/scholar-program-faq/',false,null,false,null,true),
('vanderbilt_merit','Vanderbilt Merit Scholarships','США','us',array['bachelor'],'Полное tuition на 4 года + разовая летняя стипендия (учёба за рубежом, исследования или сервис-проект); >225 получателей суммарно.',0.04,0.04,'{"academics": 9.5, "language": 8.5, "budget": 0, "sat": 7}'::jsonb,'1 декабря (ориентировочно)','12-01',null,'Официально: Vanderbilt Signature Merit Scholarships — Cornelius Vanderbilt / Ingram Scholars. FAQ прямо подтверждает: «international applicants are eligible to receive any of Vanderbilt''s merit scholarships». Нужна отдельная заявка на стипендию через MyAppVU после подачи Common App; для Ingram — 2 рекомендации о волонтёрстве.',null,'https://www.vanderbilt.edu/scholarships/faq.php',false,null,false,null,true),
('bu_presidential','BU Presidential (Бостон)','США','us',array['bachelor'],'Половина tuition (half-tuition), возобновляется до 4 лет. Прежняя Trustee Scholarship (полное tuition) на текущей официальной странице merit-стипендий больше не указана.',0.1,0.1,'{"academics": 9, "language": 8, "budget": 6, "sat": 6}'::jsonb,'1 декабря','12-01',null,'Официально: Boston University Presidential Scholarship. Иностранные студенты прямо перечислены среди тех, кто может получить merit-стипендии; отдельной заявки нет — по обычной заявке, поданной до 1 декабря. Остальные ~50% tuition и проживание — за свой счёт.',null,'https://www.bu.edu/admissions/tuition-aid/scholarships-financial-aid/first-year-merit/',false,null,false,null,true),
('alabama_intl','University of Alabama International','США','us',array['bachelor'],'Автоматические merit-стипендии по GPA 3.5+ и тестам: Presidential (SAT 1420+/ACT 32+) — $28 000 в год; Presidential Elite (SAT 1600/ACT 36, GPA 4.0) — полное tuition до 4 лет + $1 500/год + $2 000 на исследования; UA Scholar (SAT 1360+) — $24 000/год. Суммы одинаковы для out-of-state и иностранцев.',0.5,0.6,'{"academics": 8, "language": 7, "budget": 5, "sat": 7}'::jsonb,'4 декабря','12-04',null,'Официально: University of Alabama International Freshman Scholarships (Presidential / Presidential Elite). Одна из немногих «предсказуемых» схем: стипендия начисляется автоматически по баллам SAT/ACT и GPA. Требуется сдать SAT/ACT; проживание и питание не покрываются (кроме Elite — жильё 1-й год по обычной цене).',null,'https://afford.ua.edu/scholarships/international/',false,null,false,null,true),
('iwu_intl','Illinois Wesleyan (США)','США','us',array['bachelor'],'Merit-стипендии до $38 000 в год (возобновляются 4 года) автоматически по заявке; дополнительно need-based помощь для иностранцев по CSS Profile (гранты, займы, работа в кампусе).',0.3,0.3,'{"academics": 7.5, "language": 6.5, "budget": 4}'::jsonb,'1 марта','03-01',null,'Официально: Illinois Wesleyan University — International Student Merit Scholarships + need-based aid. Автоматическое рассмотрение всех подавших заявку; полное покрытие возможно только при комбинации merit + need-based (CSS Profile). Небольшой liberal-arts колледж, точная сумма зависит от оценок и тестов.',null,'https://www.iwu.edu/international/scholarships.html',false,null,false,null,true),
('minerva','Minerva University (США)','США','us',array['bachelor'],'Need-based пакет независимо от гражданства: стипендии + низкопроцентные займы + work-study до ~$5 000/год. Полная стоимость 2027/28 — $31 300 (tuition $19 900 + residential $2 800 + services $5 600); full-ride не предоставляется, семья всегда вносит вклад.',0.12,0.5,'{"academics": 8.5, "language": 7.5, "budget": 3}'::jsonb,'8 ноября','11-08',null,'Официально: Minerva University — Need-based Financial Aid for international students. Заявку на fin. aid нужно подать ДО решения о приёме, если без помощи учиться невозможно. Формат: 4 года в 7 городах мира, стоимость заметно ниже американских вузов, но не бесплатно.',null,'https://www.minerva.edu/tuition-aid/',false,null,false,null,true),
('x-davis-uwc','Davis UWC Scholars (США)','США','us',array['bachelor'],'Need-based гранты через 99 вузов-партнёров США для выпускников школ UWC, поступивших по merit; конкретные суммы на сайте не указаны (покрытие по демонстрируемой нужде).',null,null,null,'по дедлайнам вузов-партнёров (нояб–янв)',null,null,'Официально: Davis United World College Scholars Program. Только для выпускников школ UWC (казахстанцы попадают через национальный комитет UWC Kazakhstan). Отдельной заявки нет — стипендия рассматривается автоматически при поступлении в вуз-партнёр.',null,'https://www.davisuwcscholars.org/program',false,null,false,null,true),
('x-humphrey','Humphrey Fellowship (США)','США','us',array['research'],'10 месяцев (non-degree): оплата tuition и сборов в вузе-хосте, ежемесячное пособие на проживание + разовая выплата на обустройство, страховка, пособие на книги, субсидия на компьютер, международный и внутренний перелёт, средства на профразвитие (конференции, поездки).',null,null,null,'по стране — через посольство США в РК (обычно лето; approx); номинации посоль…',null,null,'Официально: Hubert H. Humphrey Fellowship Program. Для mid-career профессионалов: бакалавр + минимум 5 лет full-time опыта, лидерство и госслужба/общественная работа, ограниченный опыт в США. Не даёт степени. Точную дату дедлайна для Казахстана публикует kz.usembassy.gov (страница не открылась автоматически — проверить вручную).',null,'https://www.humphreyfellowship.org/how-to-apply/frequently-asked-questions/',false,null,false,null,true),
('x-educationusa-of','EducationUSA Opportunity Funds','США','us',array['bachelor','master'],'Не стипендия на обучение, а покрытие стартовых расходов на поступление: тесты (SAT/TOEFL), application fees, авиабилет — для сильных малообеспеченных абитуриентов, которые с высокой вероятностью получат полное fin. aid от вуза США.',null,null,null,'по циклу советников EducationUSA в РК (обычно весна–лето; approx)',null,null,'Официально: EducationUSA Opportunity Funds Program. Отбор советником EducationUSA, региональным менеджером и Public Affairs посольства США; нужен доход семьи ниже порога и высокие академические результаты. Список стран на официальной странице не приведён — участие Казахстана подтверждать у центра EducationUSA в Астане/Алматы.',null,'https://educationusa.state.gov/us-higher-education-professionals/special-programs',false,null,false,null,true),
('mccall_macbain','McCall MacBain (McGill)','Канада','ca',array['master'],'Полное tuition и сборы за всю нормативную длительность магистратуры/профессиональной программы McGill + CAD 2 300/мес в учебные семестры + грант на переезд в Монреаль + до CAD 5 000 на летние инициативы. Для иностранцев: 10 полных стипендий, 25 Finalist Awards по CAD 20 000/год (до 2 лет), 15 Regional Awards по CAD 10 000.',0.05,0.95,'{"academics": 9, "language": 7.5, "budget": 0}'::jsonb,'19 августа','08-19','06-01','Официально: McCall MacBain Scholarships (McGill University). Бакалавр должен быть получен не ранее 5 лет назад (или возраст ≤30). Много этапов: заявка, региональные интервью, финальные интервью в Монреале; отдельно нужно поступить в программу McGill.',null,'https://mccallmacbainscholars.org/apply/',false,null,false,null,true),
('x-waterloo-entrance','Waterloo Entrance Scholarship','Канада','ca',array['bachelor'],'CAD 10 000 (по CAD 5 000 за семестр) автоматически всем иностранным первокурсникам full-time (кроме ряда программ: медицина, оптометрия, фармация, social work, transfer). Дополнительно конкурсные Faculty of Mathematics Global Scholarships до CAD 40 000 и Faculty of Science до CAD 80 000 (отдельная заявка).',null,null,null,'автоматически при поступлении (решения с апреля); факультетские — по дедлайна…',null,null,'Официально: University of Waterloo — International Student Entrance Scholarship. Базовая стипендия покрывает лишь ~20–25% годового tuition для иностранцев; крупные суммы — только конкурсные факультетские стипендии (математика, science) с отдельной заявкой.',null,'https://uwaterloo.ca/future-students/financing/scholarships/international-students',false,null,false,null,true),
('x-ucalgary-entrance','Calgary International Entrance','Канада','ca',array['bachelor'],'CAD 20 000 в год, возобновляется на 2–4 курсах при GPA ≥2.60 (до CAD 80 000 за 4 года). Всего 2 награды в год.',null,null,null,'через портал My UCalgary (High School Prestige Awards); дата на странице не у…',null,null,'Официально: University of Calgary International Entrance Scholarship. Только для иностранцев, платящих international tuition; всего 2 стипендии в год — очень высокий конкурс; нужна отдельная заявка в портале после подачи документов.',null,'https://www.ucalgary.ca/registrar/awards/university-calgary-international-entrance-scholarship',false,null,false,null,true),
('york_intl','York President''s International','Канада','ca',array['bachelor'],'PISE: CAD 180 000 (CAD 45 000/год × 4). Автоматические: York International Scholarship of Distinction — CAD 37 500 суммарно при среднем ≥85%; International Merit Award — CAD 25 000 при 80–84.9%; Entrance Award — CAD 5 000 при 75–79.9%. Гарантия общежития на 4 года.',0.1,0.1,'{"academics": 9, "language": 7, "budget": 3}'::jsonb,'27 января','01-27',null,'Официально: York University — President''s International Scholarship of Excellence + International Scholarship of Distinction. PISE требует академического превосходства, волонтёрства и лидерства + номинации/рекомендации школы; автоматические стипендии дают лишь частичное покрытие (~10–25% стоимости).',null,'https://futurestudents.yorku.ca/financing-your-degree/international-scholarships',false,null,false,null,true),
('dal_entrance','Dalhousie Entrance Awards','Канада','ca',array['bachelor'],'2 000+ entrance awards ежегодно от CAD 1 000 до CAD 80 000 (в год / за 4 года, часть возобновляемые до 4 лет) по успеваемости (обычно ≥80% или 26 IB), лидерству, нужде и т.д. Иностранцы eligible.',0.35,0.35,'{"academics": 7.5, "language": 6.5, "budget": 5}'::jsonb,'15 февраля','02-15','10-01','Официально: Dalhousie University — General Entrance Award Program. Единая заявка на все entrance awards; крупные именные награды часто с региональными ограничениями (Карибы, Индия, Ямайка) — казахстанцу реально рассчитывать на общий пул по среднему баллу. Schulich Leader и Harrison McCain — только для канадцев.',null,'https://www.dal.ca/admissions/money_matters/awards-financial-aid/scholarships/prospective_students.html',false,null,false,null,true),
('x-western-nsp','Western University NSP','Канада','ca',array['bachelor'],'3 стипендии по CAD 100 000 (на 4 года) для иностранных (visa) студентов.',null,null,null,'заявка доступна с середины ноября; дедлайн — зима (обычно февраль, approx)',null,'11-15','Официально: Western University — International President''s Entrance Scholarship (National Scholarship Program). Обязательна номинация школы (школа может выдвинуть до 4 учеников + 1 дополнительно, если он иностранный) и средний балл ≥90% по Grade 12 (или эквивалент). Всего 3 награды — очень высокий конкурс.',null,'https://registrar.uwo.ca/student_finances/scholarships_awards/admission/national_scholarship_program.html',false,null,false,null,true),
('study_in_saudi','Study in Saudi Arabia (гос. платформа)','Саудовская Аравия','sa',array['bachelor','master','phd'],'Категории Fully Funded (полное покрытие обучения в госвузах КСА, по правилам МОН — стипендия, общежитие, билеты, медстраховка; суммы на платформе не указаны), Partially Funded и Self-Funded. Заявка в несколько вузов одновременно.',0.3,0.85,'{"academics": 6, "language": 3, "budget": 0}'::jsonb,'6 октября (ориентировочно)','10-06','09-16','Официально: Study in Saudi Arabia — стипендии Министерства образования КСА для иностранцев (единая платформа). Единый портал МОН КСА (studyinsaudi.sa), через который подаются заявки в KSU, IUM, KAU, UQU и др. Для арабоязычных программ обязателен подготовительный год арабского; возрастные лимиты по уровням (у KAU: магистратура ≤35, PhD ≤40).',null,'https://studyinsaudi.sa/en',false,null,true,null,true),
('ksu_intl','King Saud University (Эр-Рияд)','Саудовская Аравия','sa',array['bachelor'],'Освобождение от tuition, общежитие и льготное питание, ежемесячная стипендия + пособие за 2 месяца при приезде, авиабилет при зачислении и ежегодные билеты, медобслуживание студента и семьи, пособие на пересылку книг после выпуска (конкретные суммы в SAR в буклете не указаны).',0.3,0.85,'{"academics": 6, "language": 3, "budget": 0}'::jsonb,'18 сентября (ориентировочно)','09-18','08-18','Официально: King Saud University — International Scholarship Program (Riyadh). Возраст 17–25, аттестат не старше 5 лет со средним «очень хорошо», справка о несудимости, медосмотр, не получал ранее стипендию саудовского вуза. Отбор конкурсный по квотам на страну; сначала год арабского языка.',null,'https://faculty.ksu.edu.sa/sites/default/files/KSU%20Scholarship%20Flyer%20EN.pdf',false,null,true,null,true),
('x-kau-jeddah','King Abdulaziz University (Джидда)','Саудовская Аравия','sa',array['bachelor','master','phd','language-year'],'Покрытие tuition, проживания и расходов на жизнь, медстраховка, академическое сопровождение; программа Arabic Language Diploma. Суммы стипендии на странице не указаны.',null,null,null,'через платформу Study in Saudi (окна по семестрам)',null,null,'Официально: King Abdulaziz University (KAU, Jeddah) — International Scholarships. Магистратура — до 35 лет, PhD — до 40; средний балл «очень хорошо», 2 рекомендации, TOEFL iBT 61 / IELTS 5 (кроме арабистики и исламоведения), номинационное письмо от компетентного органа своей страны. Медицинские программы для иностранцев закрыты.',null,'https://graduatestudies.kau.edu.sa/content-306-EN-278671',false,null,false,null,true),
('x-iu-madinah','Исламский университет Медины','Саудовская Аравия','sa',array['bachelor','language-year'],'Полная стипендия по линии МОН КСА (обучение бесплатно; по практике вуза — общежитие, ежемесячная стипендия, билеты; конкретные суммы на официальной странице не указаны). Подача через studyinsaudi.moe.gov.sa.',null,null,null,'по окнам платформы Study in Saudi (approx)',null,null,'Официально: Islamic University of Madinah — Undergraduate Scholarship for international students. Традиционно много студентов из Казахстана; исламские науки, арабский, а также инженерия и естественные науки. Ограничения по возрасту и требования к аттестату — как у стипендий МОН КСА; только мужские программы на основном кампусе.',null,'https://iu.edu.sa/%D8%AA%D9%82%D8%AF%D9%8A%D9%85-%D8%B7%D9%84%D8%A8-%D8%A7%D9%84%D9%82%D8%A8%D9%88%D9%84-%D9%84%D9%84%D8%B7%D9%84%D8%A7%D8%A8-%D8%A7%D9%84%D8%AF%D9%88%D9%84%D9%8A%D9%8A%D9%86-0',false,null,false,null,true),
('alfaisal','Alfaisal University (Эр-Рияд)','Саудовская Аравия','sa',array['bachelor'],'Частичные скидки: merit — 20% tuition (по SAT/ACT/IB, удержание GPA 3.25); need-based — 20% (GPA 2.75); Distinguished Science (College of Science) — 50% tuition. Проживание и стипендия не покрываются.',0.4,0.5,'{"academics": 7, "language": 6, "budget": 5}'::jsonb,'28 июля','07-28',null,'Официально: Alfaisal University (Riyadh) — Merit / Need-based / Distinguished Science Scholarships. Частный вуз, скидки нельзя суммировать (merit ИЛИ need-based); максимум 50% и только для College of Science. Подходит как «бюджетный» вариант, но не как полная стипендия.',null,'https://admissions.alfaisal.edu/en/scholarship',false,null,false,null,true),
('aus_presidents','AUS President''s Scholarship (Шарджа)','ОАЭ','ae',array['bachelor'],'100% tuition и лабораторных сборов, ежемесячная стипендия на весь срок (сумма не указана), общежитие, 3 авиабилета туда-обратно за время учёбы, медстраховка, отмена application fee.',0.08,0.08,'{"academics": 9, "language": 7, "budget": 3}'::jsonb,'19 марта (ориентировочно)','03-19','01-15','Официально: American University of Sharjah — President''s Scholarship. Только для окончивших школу ЗА ПРЕДЕЛАМИ ОАЭ (казахстанские школы подходят): средний балл 98% за 10–11 классы, IELTS 7.0 / TOEFL iBT 94. Также автоматические merit-скидки 10–20% при 95%+.',null,'https://www.aus.edu/admissions/financial-grants-and-scholarships',false,null,false,null,true),
('x-aus-assistantships','AUS Graduate Assistantships (Шарджа)','ОАЭ','ae',array['master','phd'],'Master''s: освобождение до 9 кредитов/семестр и/или стипендия до AED 20 000 за семестр (макс. 2 года). PhD: полное освобождение от tuition + ежемесячная стипендия (макс. 4 года) + скидка 50% на общежитие.',null,null,null,'по дедлайнам graduate-приёма (весна для осеннего набора; approx)',null,null,'Официально: American University of Sharjah — Graduate Assistantships (Master''s / PhD). Требуется GPA ≥3.25 и обязательства ассистента (преподавание/исследования); количество мест ограничено бюджетом кафедр, выделяется после приёма.',null,'https://www.aus.edu/admissions/financial-grants-and-scholarships',false,null,false,null,true),
('x-uaeu-chancellor','UAEU Chancellor''s Scholarship','ОАЭ','ae',array['bachelor'],'Скидка на tuition: 100% при среднем ≥98% за 12 класс (IELTS 7.5 / TOEFL iBT 105, SAT Math 730 или ACT Math 32) или 75% при ≥95%; для талантов (инновации, искусство, спорт, технологии) — 100% или 50%. Общежитие и application fee не покрываются.',null,null,null,'1-й семестр: май–июль; 2-й семестр: сентябрь–ноябрь',null,'05-01','Официально: United Arab Emirates University (UAEU) — Chancellor''s Scholarship for Elite / Talented International Students. Государственный вуз ОАЭ, принимает иностранцев с 2021 г.; для удержания 100% нужен GPA 3.8 и ≥15 кредитов в семестр. Проживание — за свой счёт.',null,'https://www.uaeu.ac.ae/en/admission/undergraduate-scholarships.shtml',false,null,false,null,true),
('auc_excellence','AUC Excellence (Каир)','Египет','eg',array['bachelor'],'Суммируемые (stackable) стипендии от 20% до 100% tuition: Academic Achievement 20–60%, International Diversity 20–30%, Talents 20–30%, Leadership 20–30%, Liberal Arts 20–30%. Проживание не входит.',0.2,0.2,'{"academics": 8, "language": 6.5, "budget": 3}'::jsonb,'1 июня','06-01',null,'Официально: The American University in Cairo (AUC) — Excellence Scholarship Program. Есть отдельная категория «International Diversity» для иностранцев; 100% достижимо только при сочетании нескольких категорий и ранней подаче (до 1 марта — выше процент). Донорские стипендии с жильём и стипендией имеют свои критерии.',null,'https://www.aucegypt.edu/admissions/scholarships/excellence-program',false,null,false,null,true),
('x-weizmann','Weizmann Institute MSc/PhD','Израиль','il',array['master','phd'],'Обучение бесплатно (no tuition) + полная стипендия всем MSc и PhD студентам на проживание (сумма на странице не указана); обучение на английском.',null,null,null,'rolling; приём стремятся завершить к июню (approx)',null,null,'Официально: Weizmann Institute of Science — Feinberg Graduate School MSc/PhD full scholarships. Только естественные науки, математика, computer science и науки о жизни (research-based MSc/PhD). Приём открыт для любых национальностей; рассмотрение 4–12 недель, желательно заранее списаться с научной группой.',null,'https://www.weizmann.ac.il/feinberg/admissions/admissions-procedures',false,null,false,null,true),
('rotary_peace','Rotary Peace Fellowship','Международные',null,array['master'],'Полное покрытие tuition и сборов, проживание и питание, перелёт туда-обратно, расходы на стажировку и полевое исследование. До 50 master''s-стипендий (15–24 мес. в Rotary Peace Centers: Duke/UNC, Bradford, Uppsala, ICU Tokyo, Queensland) и до 120 сертификатных (1 год).',0.12,0.95,'{"academics": 7.5, "language": 6.5, "budget": 0}'::jsonb,'31 мая','05-31','02-01','Официально: Rotary Peace Fellowship (Rotary Foundation). Нужно ≥3 лет full-time опыта в сфере мира/развития (для сертификата — ≥5), TOEFL/IELTS, поддержка местного Rotary-дистрикта; учиться нужно вне своей страны. Члены Rotary и их дети/внуки не допускаются.',array['hum','law'],'https://www.rotary.org/get-involved/our-programs/peace-fellowships/how-to-become-a-rotary-peace-fellow',false,null,false,null,true),
('x-msca-doctoral-networks','MSCA Doctoral Networks (PhD)','ЕС','eu',array['phd'],'Трудовой контракт на 3–36 месяцев (до 48 для joint doctorates) с living allowance, mobility allowance и при необходимости family/long-term leave/special needs allowances (суммы установлены Work Programme MSCA; на странице не приведены).',null,null,null,'вакансии круглый год на EURAXESS; конкурс консорциумов 2026: 28 мая — 24 ноября',null,null,'Официально: Marie Skłodowska-Curie Actions — Doctoral Networks (MSCA DN, Horizon Europe). Любая национальность; нельзя иметь PhD и нельзя было жить/работать в стране принимающей организации >12 месяцев за последние 36. Заявка подаётся не в ЕС, а напрямую на позицию PhD в конкретном проекте через EURAXESS.',null,'https://marie-sklodowska-curie-actions.ec.europa.eu/actions/doctoral-networks/6-steps-to-prepare-your-application',false,null,false,null,true),
('x-mexico-amexcid','Стипендии правительства Мексики','Мексика','mx',array['master','research','bachelor-exchange'],'Модальности 2026: академическая мобильность для бакалавров/магистрантов (до 12 мес.), полная магистратура (до 24 мес.), исследовательские стажировки (6–12 мес.). Ежемесячная стипендия в MXN, освобождение от tuition в вузах-участниках и медстраховка — суммы на доступной странице не указаны (официальный gob.mx не открылся автоматически).',null,null,null,'22 июня (ориентировочно)','06-22',null,'Официально: Becas de Excelencia del Gobierno de México para Extranjeros (SRE / AMEXCID). Требуется владение испанским и предварительное принятие мексиканским вузом из списка. Список стран-участниц публикуется в convocatoria на gob.mx — страница блокирует автоматический доступ, поэтому включение Казахстана нужно проверить вручную перед подачей.',null,'https://www.gob.mx/amexcid/acciones-y-programas/becas-para-extranjeros-29785',false,null,false,null,true)
