-- 040 · Каталог, партия 3 (web-70): 124 новых программ (81 промоделировано, 43 каталогом),
-- 6 дублей помечены через duplicate_of. Все новые строки verified=false —
-- сверка человеком по source_url ещё впереди. Идемпотентно: повторный запуск
-- обновляет те же строки и не создаёт новых.
-- Источники: официальные страницы вузов/министерств/фондов (source_url), цикл 2026→2027.
on conflict (id) do update set
  name = excluded.name, country = excluded.country, cc = excluded.cc, levels = excluded.levels,
  funding = excluded.funding, base_adm = excluded.base_adm, base_sch = excluded.base_sch, req = excluded.req,
  deadline = excluded.deadline, deadline_md = excluded.deadline_md, apply_open_md = excluded.apply_open_md,
  note = excluded.note, fields = excluded.fields, source_url = excluded.source_url,
  lang_year = excluded.lang_year, exam = excluded.exam, available_kz = excluded.available_kz,
  updated_at = now()
where programs.verified = false;   -- проверенные человеком строки не трогаем

-- дубли уже существующих записей (оригинал остаётся, дубль уходит из витрин)
update programs set duplicate_of = 'nawa', updated_at = now() where id = 'nawa_banach' and duplicate_of is null and exists (select 1 from programs where id = 'nawa');
update programs set duplicate_of = 'tudelft_vef', updated_at = now() where id = 'x-tu-delft-excellence-justus-louise-van-effen' and duplicate_of is null and exists (select 1 from programs where id = 'tudelft_vef');
update programs set duplicate_of = 'ubc_isp', updated_at = now() where id = 'x-ubc-international-scholars-imes-karen-mckellin' and duplicate_of is null and exists (select 1 from programs where id = 'ubc_isp');
update programs set duplicate_of = 'qatar_uni', updated_at = now() where id = 'x-qatar-university-international-scholarships' and duplicate_of is null and exists (select 1 from programs where id = 'qatar_uni');
update programs set duplicate_of = 'anso', updated_at = now() where id = 'x-anso-scholarship-chinese-academy-of-sciences' and duplicate_of is null and exists (select 1 from programs where id = 'anso');
update programs set duplicate_of = 'cis_cn', updated_at = now() where id = 'x-confucius-institute-scholarship' and duplicate_of is null and exists (select 1 from programs where id = 'cis_cn');

-- гигиена: код страны uk → gb (ISO), как у остальных британских строк
update programs set cc = 'gb', country = 'Великобритания', updated_at = now() where id = 'weidenfeld' and cc = 'uk';

-- контроль
select count(*) as programs_public from programs_public;
select count(*) as programs_engine from programs_engine;
select count(distinct cc) as countries from programs_public where cc is not null;
